@skipUnless(_NATIVE_WIRE_ENABLED, "requires TEST_NATIVE_TYPE_KERNEL=1 and type_kernel ext")
class NativeMethodFullnameSuite(Suite):
    """Parity tests for M25: checkexpr `method_fullname` ported to Rust.

    Each test serializes a `mypy.types.Type` and asks both
    `type_kernel.rust_method_fullname(resolver, bytes, name)` and the
    pure-Python `ExpressionChecker.method_fullname` for the qualified
    method name, asserting they agree. The Rust side defers (None) to
    Python for any case the kernel cannot decide, so the assertion is:
    Rust result if non-None, else the Python result, equals the Python
    result.
    """

    def setUp(self) -> None:
        from mypy.checkexpr import _set_native_checkexpr_active

        self.fx = TypeFixture()
        # The containing-type cases (TypedDict, Literal) resolve "foo"
        # through the fallback's names table, so inject it before the
        # resolver snapshots member_info.
        from mypy.nodes import MDEF, SymbolTableNode, Var

        self._injected = Var("foo")
        self.fx.ai.names["foo"] = SymbolTableNode(MDEF, self._injected)
        type_infos = [
            self.fx.oi,
            self.fx.ai,
            self.fx.bi,
            self.fx.ci,
            self.fx.di,
            self.fx.ei,
            self.fx.e2i,
            self.fx.e3i,
            self.fx.fi,
            self.fx.f2i,
            self.fx.f3i,
            self.fx.gi,
            self.fx.g2i,
            self.fx.hi,
            self.fx.gsi,
            self.fx.gs2i,
            self.fx.std_tuplei,
            self.fx.std_listi,
            self.fx.type_typei,
            self.fx.bool_type_info,
            self.fx.str_type_info,
            self.fx.functioni,
        ]
        self.resolver = _type_kernel.build_native_resolver(type_infos, [])
        self._set_active = _set_native_checkexpr_active
        self._set_active(False)

    def tearDown(self) -> None:
        del self.fx.ai.names["foo"]
        self._set_active(False)

    def _bytes_of(self, t: Type) -> bytes:
        buf = _WriteBuffer()
        t.write(buf)
        return buf.getvalue()

    def assert_fullname_par(self, t: Type, method_name: str) -> None:
        # Python reference via the pure-Python path (gate off).
        from mypy.checkexpr import ExpressionChecker

        self._set_active(False)
        py = ExpressionChecker.method_fullname(None, t, method_name)  # type: ignore[arg-type]
        rusted = _type_kernel.rust_method_fullname(self.resolver, self._bytes_of(t), method_name)
        assert (
            rusted if rusted is not None else py
        ) == py, f"method_fullname({t!r}, {method_name!r}) rust={{}} py={{}}".format(rusted, py)

    def test_instance(self) -> None:
        self.assert_fullname_par(self.fx.a, "foo")
        self.assert_fullname_par(self.fx.b, "foo")

    def test_plain_tuple(self) -> None:
        plain = TupleType([self.fx.a], self.fx.std_tuple)
        self.assert_fullname_par(plain, "foo")

    def test_type_type(self) -> None:
        self.assert_fullname_par(self.fx.type_a, "foo")
        self.assert_fullname_par(self.fx.type_any, "foo")

    def test_callable_type_obj(self) -> None:
        # A class-object callable: fallback is builtins.type (metaclass), so
        # both sides unwrap to the constructed instance.
        c = CallableType([], [], [], self.fx.a, Instance(self.fx.type_typei, []))
        self.assert_fullname_par(c, "foo")

    def test_typeddict(self) -> None:
        td = TypedDictType({"x": self.fx.o}, {"x"}, set(), Instance(self.fx.ai, []))
        self.assert_fullname_par(td, "foo")

    def test_literal(self) -> None:
        lit = LiteralType(1, Instance(self.fx.ai, []))
        self.assert_fullname_par(lit, "foo")

    def test_instance_missing_method(self) -> None:
        # Instance branch appends unconditionally (no names lookup).
        self.assert_fullname_par(self.fx.a, "missing")

    def test_unknown_type_defers(self) -> None:
        # NoneType is not Instance/TypedDict/Literal/Tuple: both defer to
        # None. The Rust side returns None and Python re-runs.
        self.assert_fullname_par(self.fx.nonet, "foo")
        self.assert_fullname_par(self.fx.anyt, "foo")


@skipUnless(_NATIVE_WIRE_ENABLED, "requires TEST_NATIVE_TYPE_KERNEL=1 and type_kernel ext")
class NativeJoinTypeListSuite(Suite):
    """Parity suite for the Rust `join_type_list` fold port
    (join.py:1508-1529, checker_helpers.rs `join_type_list_inner`).

    With the native join gate on, `join_type_list` serializes the list
    and folds it pairwise through `rust_join_type_list` (one setops pair
    join per accumulator step); arg-bearing Instance-Instance pairs the
    prejoin cannot decide route through the `join_instances_core`
    engine. The whole call defers (`None`) for lists carrying a
    last_known_value outside the relaxed shape (non-plain-class or
    args-bearing LKV Instances), `fallback_to_any` classes, or
    identity-unsafe items; the Python shim then re-runs the identical
    pure fold. Plain-class args-less same-ref LKV pairs decide via the
    prejoin (fresh Instance, LKV and extra_attrs dropped).
    Length <= 1 lists never cross the FFI boundary (Python early return
    before the gate). Every test asserts the gate-off vs gate-on
    results are identical, and a direct seam call proves Rust
    engagement for the decided cases and deferral for the guarded ones.
    """

    def setUp(self) -> None:
        from mypy.join import (
            _set_native_join_active,
            _set_native_join_resolver,
            _set_native_join_typeinfo_map,
        )
        from mypy.subtypes import _set_native_subtype_active, _set_native_subtype_resolver

        self.fx = TypeFixture()
        type_infos = self._collect_type_infos()
        self.resolver = _type_kernel.build_native_resolver(type_infos, [])
        typeinfo_map = {info.fullname: info for info in type_infos}
        _set_native_subtype_active(True)
        _set_native_subtype_resolver(self.resolver)
        _set_native_join_active(True)
        _set_native_join_resolver(self.resolver)
        _set_native_join_typeinfo_map(typeinfo_map)

    def tearDown(self) -> None:
        from mypy.join import (
            _set_native_join_active,
            _set_native_join_resolver,
            _set_native_join_typeinfo_map,
        )
        from mypy.subtypes import _set_native_subtype_active, _set_native_subtype_resolver

        _set_native_subtype_active(False)
        _set_native_subtype_resolver(None)
        _set_native_join_active(False)
        _set_native_join_resolver(None)
        _set_native_join_typeinfo_map(None)

    def _collect_type_infos(self) -> list[TypeInfo]:
        infos = []
        for name in dir(self.fx):
            if not name.endswith("i"):
                continue
            value = getattr(self.fx, name)
            if _is_type_info(value):
                infos.append(value)
        return infos

    def _with_gate(self, active: bool, fn: Callable[[], T]) -> T:
        import mypy.join

        old = mypy.join._native_join_active
        mypy.join._set_native_join_active(active)
        try:
            return fn()
        finally:
            mypy.join._set_native_join_active(old)

    def _assert_parity(self, types: list[Type]) -> object:
        from mypy.join import join_type_list

        off = self._with_gate(False, lambda: join_type_list(list(types)))
        on = self._with_gate(True, lambda: join_type_list(list(types)))
        assert_equal(on, off)
        return on

    def _seam_result(self, types: list[Type]) -> object:
        from mypy.join import _serialize_type

        blobs = [_serialize_type(t) for t in types]
        return _type_kernel.rust_join_type_list(blobs, True, self.resolver)

    def test_empty_list_uninhabited(self) -> None:
        # join.py:1509-1517: length <= 1 lists never cross the gate.
        from mypy.join import join_type_list

        on = self._assert_parity([])
        assert isinstance(on, UninhabitedType)
        assert join_type_list([self.fx.a]) == self.fx.a

    def test_nle1_lists_never_cross_ffi(self) -> None:
        # Locks the n<=1 early return (join.py:1510-1515) with the gate
        # on from setUp. Uses RuntimeError, not AssertionError: the shim
        # catches AssertionError and would fall back to the pure body.
        from mypy.join import join_type_list

        def forbid(*args: object) -> object:
            raise RuntimeError("length <= 1 lists must never cross the FFI")

        original = _type_kernel.rust_join_type_list
        _type_kernel.rust_join_type_list = forbid  # type: ignore[assignment]
        try:
            empty = join_type_list([])
            assert isinstance(get_proper_type(empty), UninhabitedType)
            item = self.fx.a
            assert join_type_list([item]) is item
        finally:
            _type_kernel.rust_join_type_list = original

    def test_duplicate_same_instances(self) -> None:
        # [A, A] -> A (the args-less prejoin's same-ref arm).
        assert self._assert_parity([self.fx.a, self.fx.a]) == self.fx.a
        assert self._seam_result([self.fx.a, self.fx.a]) is not None

    def test_subtype_dominated(self) -> None:
        # [B, A] -> A (B <: A, the supertype wins the fold).
        assert self._assert_parity([self.fx.b, self.fx.a]) == self.fx.a

    def test_unrelated_instances_join_to_object(self) -> None:
        # [A, D] -> object: the prejoin defers on the unrelated pair and
        # the fold routes through the join_instances_core nominal arm.
        assert self._assert_parity([self.fx.a, self.fx.d]) == self.fx.o
        assert self._seam_result([self.fx.a, self.fx.d]) is not None

    def test_covariant_same_class_args(self) -> None:
        # [G[A], G[B]] -> G[A]: the arg-bearing pair routes through
        # visit_instance_with_args (covariant argwise fold).
        assert self._assert_parity([self.fx.ga, self.fx.gb]) == self.fx.ga
        assert self._seam_result([self.fx.ga, self.fx.gb]) is not None

    def test_any_absorbs(self) -> None:
        # [Any, A] -> Any (the setops Any short-circuit in the fold).
        assert self._assert_parity([self.fx.anyt, self.fx.a]) == self.fx.anyt
        assert self._seam_result([self.fx.anyt, self.fx.a]) is not None

    def test_lkv_list_decides_via_prejoin(self) -> None:
        # Same-ref args-less LKV Instances of a plain class decide via the
        # prejoin: Python's fold rebuilds the fresh instances and joins
        # them to the LKV-less class (join.py:392), dropping both LKVs.
        from mypy.types import LiteralType

        lit_a = Instance(self.fx.ai, [], last_known_value=LiteralType(1, self.fx.a))
        lit_b = Instance(self.fx.ai, [], last_known_value=LiteralType(2, self.fx.a))
        assert self._seam_result([lit_a, lit_b]) is not None
        self._assert_parity([lit_a, lit_b])

    def test_fallback_to_any_list_defers(self) -> None:
        # A fallback_to_any class (stub / unknown base) absorbs into
        # Any in Python but the wire kernel cannot reproduce that, so
        # the whole list defers to the pure-Python fold.
        from mypy.join import _serialize_type
        from mypy.nodes import MDEF, SymbolTableNode, Var as VarNode

        dyn_i = self.fx.make_type_info("mod.DynStub")
        dyn_i.fallback_to_any = True
        dyn_i.names["x"] = SymbolTableNode(MDEF, VarNode("x", AnyType(TypeOfAny.explicit)))
        infos = self._collect_type_infos() + [dyn_i]
        resolver = _type_kernel.build_native_resolver(infos, [])
        dyn = Instance(dyn_i, [])
        types = [dyn, self.fx.a]
        blobs = [_serialize_type(t) for t in types]
        assert _type_kernel.rust_join_type_list(blobs, True, resolver) is None

    def test_missing_snapshot_list_defers(self) -> None:
        # An item whose TypeInfo is absent from the resolver: the pair
        # cannot decide, the whole call defers to the Python fold.
        from mypy.join import _serialize_type

        missing = self.fx.make_type_info("mod.Missing")
        types: list[Type] = [Instance(missing, []), self.fx.a]
        blobs = [_serialize_type(t) for t in types]
        assert _type_kernel.rust_join_type_list(blobs, True, self.resolver) is None

    def test_three_way_fold(self) -> None:
        # A longer list exercises the accumulator chain, not just one
        # pair: [B, A, A] -> A.
        assert self._assert_parity([self.fx.b, self.fx.a, self.fx.a]) == self.fx.a


@skipUnless(_NATIVE_WIRE_ENABLED, "requires TEST_NATIVE_TYPE_KERNEL=1 and type_kernel ext")
class NativeTypeTypeContextSuite(Suite):
    """Parity suite for the Rust `is_type_type_context` port (Phase B3a, #591).

    Exercises TypeType, unions, and the alias-expansion path: an alias
    whose frozen target is `Type[X]` must answer True without deferring,
    while `List[X]` targets answer False. The native resolver is built
    from the TypeFixture type_infos and a real `TypeAlias` whose `target`
    is serialized through the fixture, matching production's
    `build_native_resolver` alias snapshot. Requires TEST_NATIVE_TYPE_KERNEL=1.
    """

    def setUp(self) -> None:
        from mypy.checkexpr import _set_native_checkexpr_active, _set_native_checkexpr_resolver

        self.fx = TypeFixture()
        self.resolver = self._build_resolver([])
        _set_native_checkexpr_resolver(self.resolver)
        _set_native_checkexpr_active(True)

    def tearDown(self) -> None:
        from mypy.checkexpr import _set_native_checkexpr_active, _set_native_checkexpr_resolver

        _set_native_checkexpr_active(False)
        _set_native_checkexpr_resolver(None)

    def _build_resolver(self, aliases: list[Any]) -> Any:
        return _type_kernel.build_native_resolver(
            [
                self.fx.oi,
                self.fx.ai,
                self.fx.bi,
                self.fx.str_type_info,
                self.fx.type_typei,
                self.fx.std_tuplei,
                self.fx.std_listi,
            ],
            aliases,
        )

    def _rebuild_with_aliases(self, aliases: list[Any]) -> None:
        from mypy.checkexpr import _set_native_checkexpr_resolver

        self.resolver = self._build_resolver(aliases)
        _set_native_checkexpr_resolver(self.resolver)

    def assert_par(self, t: Type, expected: bool) -> None:
        from mypy.checkexpr import _serialize_type_for_checkexpr, is_type_type_context

        assert is_type_type_context(t) is expected
        # The Rust side must actually decide (non-None) for the alias
        # cases, proving the resolver snapshot expansion fired rather than
        # falling back to Python's `get_proper_type`.
        rusted = _type_kernel.rust_is_type_type_context(
            self.resolver, _serialize_type_for_checkexpr(t)
        )
        assert rusted is not None, f"Rust deferred on {t!r}"
        assert rusted is expected

    def test_type_type(self) -> None:
        self.assert_par(TypeType(self.fx.a), True)

    def test_plain_instance(self) -> None:
        self.assert_par(self.fx.a, False)

    def test_union_with_type_type(self) -> None:
        self.assert_par(UnionType.make_union([self.fx.a, TypeType(self.fx.b)]), True)

    def test_union_without_type_type(self) -> None:
        self.assert_par(UnionType.make_union([self.fx.a, self.fx.b]), False)

    def test_alias_to_type_type(self) -> None:
        # TypeAlias whose target is Type[A]: the Rust side expands the
        # alias via the resolver snapshot and answers True without defer.
        from mypy.nodes import TypeAlias

        alias = TypeAlias(TypeType(self.fx.a), "mod.TA", "mod", -1, -1)
        self._rebuild_with_aliases([alias])
        self.assert_par(TypeAliasType(alias, []), True)

    def test_alias_to_list_false(self) -> None:
        from mypy.nodes import TypeAlias

        alias = TypeAlias(Instance(self.fx.std_listi, [self.fx.a]), "mod.TB", "mod", -1, -1)
        self._rebuild_with_aliases([alias])
        self.assert_par(TypeAliasType(alias, []), False)

    def test_union_with_alias_to_type_type(self) -> None:
        from mypy.nodes import TypeAlias

        alias = TypeAlias(TypeType(self.fx.b), "mod.TC", "mod", -1, -1)
        self._rebuild_with_aliases([alias])
        self.assert_par(UnionType.make_union([self.fx.a, TypeAliasType(alias, [])]), True)

    def test_nested_alias_to_type_type(self) -> None:
        # B = A, A = Type[A]; the snapshot chain must be followed and the
        # Rust side must answer True without defer (Python expands both).
        from mypy.nodes import TypeAlias

        alias_a = TypeAlias(TypeType(self.fx.a), "mod.TA", "mod", -1, -1)
        alias_b = TypeAlias(TypeAliasType(alias_a, []), "mod.TB", "mod", -1, -1)
        self._rebuild_with_aliases([alias_a, alias_b])
        self.assert_par(TypeAliasType(alias_b, []), True)


@skipUnless(_NATIVE_WIRE_ENABLED, "requires TEST_NATIVE_TYPE_KERNEL=1 and type_kernel ext")
class NativeCheckexprFunctionsDeferralSuite(Suite):
    """Differential parity for the #871 checkexpr_functions alias defers.

    Ports top-level TypeAliasType operand expansion into the
    `has_bytes_component` and `allow_fast_container_literal` seams,
    mirroring the `get_proper_type` calls at the top of the Python bodies
    (checkexpr.py). Each test runs the public function gate-off (pure
    Python) and gate-on (Rust seam) and asserts equal answers; for the
    resolved-alias cases it also calls the seam directly and asserts a
    non-None result, proving the resolver-snapshot expansion fired
    instead of deferring. A missing resolver snapshot still defers (the
    Python fallback gives the answer, so both gates agree).
    """

    def setUp(self) -> None:
        from mypy.checkexpr import _set_native_checkexpr_active, _set_native_checkexpr_resolver

        self.fx = TypeFixture()
        self.bytes_info = self.fx.make_type_info("builtins.bytes")
        self.bytearray_info = self.fx.make_type_info("builtins.bytearray")
        self.resolver = self._build_resolver([], [])
        _set_native_checkexpr_resolver(self.resolver)
        _set_native_checkexpr_active(True)

    def tearDown(self) -> None:
        from mypy.checkexpr import _set_native_checkexpr_active, _set_native_checkexpr_resolver

        _set_native_checkexpr_active(False)
        _set_native_checkexpr_resolver(None)

    def _build_resolver(self, extra_infos: list[Any], aliases: list[Any]) -> Any:
        from mypy.checkexpr import _set_native_checkexpr_resolver

        infos = [
            self.fx.oi,
            self.fx.ai,
            self.fx.bi,
            self.fx.str_type_info,
            self.fx.type_typei,
            self.fx.std_tuplei,
            self.fx.std_listi,
        ] + extra_infos
        self.resolver = _type_kernel.build_native_resolver(infos, aliases)
        _set_native_checkexpr_resolver(self.resolver)
        return self.resolver

    def _with_gate(self, active: bool, fn: Callable[[], T]) -> T:
        from mypy.checkexpr import _set_native_checkexpr_active

        _set_native_checkexpr_active(active)
        try:
            return fn()
        finally:
            _set_native_checkexpr_active(True)

    def _differential(self, fn: Callable[[], object]) -> object:
        # Gate-off (pure Python) vs gate-on (Rust seam) must agree.
        off = self._with_gate(False, fn)
        assert fn() == off
        return off

    def test_has_bytes_alias_to_bytes(self) -> None:
        from mypy.checkexpr import _serialize_type_for_checkexpr, has_bytes_component
        from mypy.nodes import TypeAlias

        alias = TypeAlias(Instance(self.bytes_info, []), "mod.AB", "mod", -1, -1)
        self._build_resolver([self.bytes_info], [alias])
        typ = TypeAliasType(alias, [])
        # Rust must decide (non-None): the alias expands to builtins.bytes.
        assert (
            _type_kernel.rust_has_bytes_component(
                self.resolver, _serialize_type_for_checkexpr(typ)
            )
            is True
        )
        assert self._differential(lambda: has_bytes_component(typ)) is True

    def test_has_bytes_union_alias_item(self) -> None:
        from mypy.checkexpr import _serialize_type_for_checkexpr, has_bytes_component
        from mypy.nodes import TypeAlias

        alias = TypeAlias(Instance(self.bytearray_info, []), "mod.ABA", "mod", -1, -1)
        self._build_resolver([self.bytearray_info], [alias])
        union = UnionType.make_union([self.fx.a, TypeAliasType(alias, [])])
        assert (
            _type_kernel.rust_has_bytes_component(
                self.resolver, _serialize_type_for_checkexpr(union)
            )
            is True
        )
        assert self._differential(lambda: has_bytes_component(union)) is True

    def test_has_bytes_non_bytes_false(self) -> None:
        from mypy.checkexpr import has_bytes_component

        assert self._differential(lambda: has_bytes_component(self.fx.a)) is False

    def test_has_bytes_alias_missing_snapshot(self) -> None:
        # Missing resolver snapshot: both gates fall through to Python's
        # get_proper_type and must agree.
        from mypy.checkexpr import has_bytes_component
        from mypy.nodes import TypeAlias

        alias = TypeAlias(Instance(self.bytes_info, []), "mod.AMissing", "mod", -1, -1)
        typ = TypeAliasType(alias, [])
        assert self._differential(lambda: has_bytes_component(typ)) is True

    def test_allow_fast_alias_to_tuple(self) -> None:
        from mypy.checkexpr import _serialize_type_for_checkexpr, allow_fast_container_literal
        from mypy.nodes import TypeAlias

        fallback = Instance(self.fx.std_tuplei, [])
        target = TupleType([Instance(self.fx.ai, []), Instance(self.fx.bi, [])], fallback)
        alias = TypeAlias(target, "mod.AT", "mod", -1, -1)
        self._build_resolver([], [alias])
        typ = TypeAliasType(alias, [])
        assert (
            _type_kernel.rust_allow_fast_container_literal(
                self.resolver, _serialize_type_for_checkexpr(typ)
            )
            is True
        )
        assert self._differential(lambda: allow_fast_container_literal(typ)) is True

    def test_allow_fast_alias_to_list(self) -> None:
        from mypy.checkexpr import _serialize_type_for_checkexpr, allow_fast_container_literal
        from mypy.nodes import TypeAlias

        alias = TypeAlias(Instance(self.fx.std_listi, [self.fx.a]), "mod.AL", "mod", -1, -1)
        self._build_resolver([], [alias])
        typ = TypeAliasType(alias, [])
        assert (
            _type_kernel.rust_allow_fast_container_literal(
                self.resolver, _serialize_type_for_checkexpr(typ)
            )
            is True
        )
        assert self._differential(lambda: allow_fast_container_literal(typ)) is True

    def test_allow_fast_plain_instance_true(self) -> None:
        from mypy.checkexpr import allow_fast_container_literal

        assert self._differential(lambda: allow_fast_container_literal(self.fx.a)) is True

    def test_allow_fast_alias_missing_snapshot(self) -> None:
        # Alias absent from the resolver: the seam defers (None), so the
        # answer comes from Python's get_proper_type; both gates agree.
        from mypy.checkexpr import _serialize_type_for_checkexpr, allow_fast_container_literal
        from mypy.nodes import TypeAlias

        alias = TypeAlias(Instance(self.fx.std_listi, [self.fx.a]), "mod.AMissL", "mod", -1, -1)
        typ = TypeAliasType(alias, [])
        assert (
            _type_kernel.rust_allow_fast_container_literal(
                self.resolver, _serialize_type_for_checkexpr(typ)
            )
            is None
        )
        assert self._differential(lambda: allow_fast_container_literal(typ)) is True


@skipUnless(_NATIVE_WIRE_ENABLED, "requires TEST_NATIVE_TYPE_KERNEL=1 and type_kernel ext")
class NativeRemoveRedundantUnionItemsSuite(Suite):
    """Parity for the Rust `_remove_redundant_union_items` port (mypy.typeops).

    The Python body runs two passes over flattened union items: forward,
    then reversed, dropping UninhabitedType, exact duplicates, and items
    that are proper subtypes of an earlier item. The Rust port mirrors the
    passes on the wire with the same `SubtypeContext` (ignore_promotions,
    proper_subtype). Toggling the typeops gate off (pure Python) and on
    (Rust seam) must produce identical results, and a direct seam call
    proves the Rust function engages rather than silently deferring.
    """

    def setUp(self) -> None:
        from mypy.typeops import _set_native_typeops_active, _set_native_typeops_resolver
        from mypy.wirefixup import set_wire_typeinfo_map

        self.fx = TypeFixture()
        self.o_info = self.fx.oi
        self.a_info = self.fx.ai
        self.b_info = self.fx.bi
        self.c_info = self.fx.ci
        self.int_info = self.fx.make_type_info("builtins.int", mro=[self.fx.oi])
        # A subclass of A for the `str(b)` naming, mirroring other suites.
        self._resolver = _type_kernel.build_native_resolver(
            [self.o_info, self.a_info, self.b_info, self.c_info, self.int_info], []
        )
        set_wire_typeinfo_map(
            {
                info.fullname: info
                for info in (self.o_info, self.a_info, self.b_info, self.c_info, self.int_info)
            }
        )
        self._live_map = {
            info.fullname: info
            for info in (self.o_info, self.a_info, self.b_info, self.c_info, self.int_info)
        }
        self._resolver.set_live_typeinfo_map(dict(self._live_map))
        _set_native_typeops_active(True)
        _set_native_typeops_resolver(self._resolver)

    def tearDown(self) -> None:
        from mypy.typeops import _set_native_typeops_active, _set_native_typeops_resolver
        from mypy.wirefixup import set_wire_typeinfo_map

        _set_native_typeops_active(False)
        _set_native_typeops_resolver(None)
        set_wire_typeinfo_map(None)

    def _with_gate(self, active: bool, fn: Callable[[], T]) -> T:
        from mypy.typeops import _set_native_typeops_active

        _set_native_typeops_active(active)
        try:
            return fn()
        finally:
            _set_native_typeops_active(True)

    def _strs(self, items: Sequence[Type]) -> list[str]:
        from mypy.typeops import _remove_redundant_union_items

        return [str(x) for x in _remove_redundant_union_items(list(items), False)]

    def _strs_erased(self, items: Sequence[Type]) -> list[str]:
        from mypy.typeops import _remove_redundant_union_items

        return [str(x) for x in _remove_redundant_union_items(list(items), True)]

    def _assert_par(self, items: Sequence[Type], label: str) -> None:
        off = self._with_gate(False, lambda: self._strs(items))
        on = self._with_gate(True, lambda: self._strs(items))
        assert_equal(on, off, f"_remove_redundant_union_items parity {label}")

    def test_exact_duplicate_dropped(self) -> None:
        items = [self.fx.a, self.fx.a]
        self._assert_par(items, "exact duplicate")
        # Also reverse the input order; both passes collapse the dup.
        self._assert_par(list(reversed(items)), "exact duplicate reversed")
        assert_equal(self._with_gate(True, lambda: self._strs(items)), ["A"])

    def test_uninhabited_dropped(self) -> None:
        items = [self.fx.a, self.fx.uninhabited, self.fx.a]
        self._assert_par(items, "uninhabited")
        assert_equal(self._with_gate(True, lambda: self._strs(items)), ["A"])

    def _int(self) -> Instance:
        return Instance(self.int_info, [])

    def test_subtype_removed(self) -> None:
        # int is a proper subtype of object, so only object survives.
        items = [self._int(), self.fx.o]
        self._assert_par(items, "int vs object")
        # Reversed order: object first, int later.
        self._assert_par([self.fx.o, self._int()], "object vs int")
        assert_equal(self._with_gate(True, lambda: self._strs(items)), ["builtins.object"])

    def test_literal_dup_same_fallback(self) -> None:
        # Two literals sharing a fallback are never duplicates of each
        # other (different values), so both survive.
        items = [self.fx.lit1, self.fx.lit2]
        self._assert_par(items, "literal same fallback")
        assert_equal(
            self._with_gate(True, lambda: self._strs(items)), ["Literal[1]", "Literal[2]"]
        )

    def test_two_pass_reversal(self) -> None:
        # Pass 1 forward: [int, object] keeps both (object is not a subtype
        # of int). Pass 2 reversed drops int as a subtype of object.
        # Same result structurally for reversed input.
        items = [self._int(), self.fx.o]
        self._assert_par(items, "two-pass forward")
        self._assert_par([self.fx.o, self._int()], "two-pass reversed")
        assert_equal(self._with_gate(True, lambda: self._strs(items)), ["builtins.object"])

    def test_lkv_item_then_plain_collapses_to_plain(self) -> None:
        # typeops.py:1420-1428: an Instance with a last_known_value never
        # removes a plain Instance of the same class; both orderings must
        # be gate-stable (issue #1335).
        from mypy.types import LiteralType

        lkv = Instance(self.int_info, [], last_known_value=LiteralType(1, self._int()))
        items = [lkv, self._int()]
        self._assert_par(items, "lkv then plain")
        self._assert_par(list(reversed(items)), "plain then lkv")
        assert_equal(
            self._with_gate(True, lambda: self._strs(items)),
            self._with_gate(False, lambda: self._strs(items)),
        )

    def test_seam_engages(self) -> None:
        from mypy.typeops import _serialize_type_list

        r = _type_kernel.rust_remove_redundant_union_items(
            _serialize_type_list([self.fx.a, self.fx.a]),
            _rru_flags_blob([self.fx.a, self.fx.a]),
            False,
            True,
            self._resolver,
        )
        assert r is not None, "Rust _remove_redundant_union_items did not engage"
        out, prov = r[0], r[1]
        assert len(out) > 0
        assert prov == [0], f"provenance must trace input 0, got {prov!r}"

    def test_mutated_survivor_keeps_original_object(self) -> None:
        # A mutated survivor whose duplicate needs no widening: the
        # provenance substitution returns the ORIGINAL live object so
        # the narrowed flag survives (the round-trip would reset it).
        from mypy.typeops import _remove_redundant_union_items, _serialize_type_list

        mut = self._int()
        mut.can_be_false = False
        items = [mut, mut]
        self._assert_par(items, "mutated survivor dedup")
        res = self._with_gate(True, lambda: _remove_redundant_union_items(list(items), False))
        assert res == [mut], f"mutated survivor must dedup, got {res!r}"
        assert res[0] is mut, "mutated survivor must keep its original object"
        assert res[0].can_be_false is False
        r = _type_kernel.rust_remove_redundant_union_items(
            _serialize_type_list(items), _rru_flags_blob(items), False, True, self._resolver
        )
        assert r is not None, "Rust deferred on mutated-survivor dedup"
        assert r[1] == [0], f"provenance must trace input 0, got {r[1]!r}"

    def test_widen_on_mutated_survivor_rebuilds(self) -> None:
        # The duplicate would widen the mutated survivor: the seam no longer
        # defers; it marks the survivor and the shim rebuilds the slot with
        # true_or_false(orig_item), a fresh flags-reset copy.
        from mypy.typeops import _remove_redundant_union_items, _serialize_type_list

        mut = self._int()
        mut.can_be_false = False
        items = [mut, self._int()]
        self._assert_par(items, "widen on mutated survivor")
        res = self._with_gate(True, lambda: _remove_redundant_union_items(list(items), False))
        assert len(res) == 1, f"mutated survivor must dedup, got {res!r}"
        assert res[0] is not mut, "widened survivor must be a fresh copy"
        assert res[0].can_be_false is True, "widen must reset can_be_false"
        assert res[0].can_be_true is True, "widen must reset can_be_true"
        r = _type_kernel.rust_remove_redundant_union_items(
            _serialize_type_list(items), _rru_flags_blob(items), False, True, self._resolver
        )
        assert r is not None, "seam must not defer on a widen-hits-mutated survivor"
        assert r[1] == [0], f"provenance must trace input 0, got {r[1]!r}"
        assert list(r[2]) == [1], f"widen mark must be set on the survivor, got {r[2]!r}"

    def test_widen_marks_only_the_widened_survivor(self) -> None:
        # Two mutated survivors, one widened by an exact duplicate, the
        # other untouched: the mark applies per output position, so the
        # untouched survivor keeps its live object; the widened one is fresh.
        from mypy.typeops import _remove_redundant_union_items, _serialize_type_list

        mut_a = self._int()
        mut_a.can_be_false = False
        mut_b = Instance(self.a_info, [])
        mut_b.can_be_false = False
        items = [mut_a, mut_b, self._int()]
        self._assert_par(items, "one widened, one untouched")
        res = self._with_gate(True, lambda: _remove_redundant_union_items(list(items), False))
        assert len(res) == 2, f"two survivors expected, got {res!r}"
        assert res[0] is not mut_a, "widened survivor must be a fresh copy"
        assert res[0].can_be_false is True, "widen must reset can_be_false"
        assert res[1] is mut_b, "untouched survivor must keep its original object"
        assert res[1].can_be_false is False, "untouched survivor must keep its mutation"
        r = _type_kernel.rust_remove_redundant_union_items(
            _serialize_type_list(items), _rru_flags_blob(items), False, True, self._resolver
        )
        assert r is not None, "seam must handle one widened survivor among two"
        assert r[1] == [0, 1], f"provenance must trace both survivors, got {r[1]!r}"
        assert list(r[2]) == [1, 0], f"widen marks must be per position, got {r[2]!r}"

    def test_keep_erased_erased_type_decodes_natively(self) -> None:
        # keep_erased=True with a surviving ErasedType item: the output
        # carries wire tag 122, which read_type refuses unless
        # _ALLOW_WIRE_ERASED_TYPE is set; the shim now opts in.
        from mypy.typeops import _serialize_type_list
        from mypy.types import ErasedType

        items = [self._int(), ErasedType()]
        off = self._with_gate(False, lambda: self._strs_erased(items))
        on = self._with_gate(True, lambda: self._strs_erased(items))
        assert_equal(on, off, "keep_erased ErasedType parity")
        assert len(on) == 2, f"both items must survive, got {on!r}"
        r = _type_kernel.rust_remove_redundant_union_items(
            _serialize_type_list(items), _rru_flags_blob(items), True, True, self._resolver
        )
        assert r is not None, "seam deferred on a surviving ErasedType"
        assert len(r[0]) > 0


@skipUnless(_NATIVE_WIRE_ENABLED, "requires TEST_NATIVE_TYPE_KERNEL=1 and type_kernel ext")
class NativeTryGettingLiteralSuite(Suite):
    """Parity for the Rust `try_getting_literal` port (mypy.checkexpr).

    `try_getting_literal` unwraps an Instance's last_known_value to the
    precise LiteralType, or returns the type proper. The Rust port
    implements the same get_proper_type + lkv unwrap; the wire round-trip
    carries the `last_known_value` field, and fixup resolves type_refs to
    live TypeInfo via the installed wire map. Toggling the checkexpr gate
    off (pure Python) and on (Rust seam) must produce identical results, and
    a direct seam call proves the Rust function engages rather than
    silently deferring.
    """

    def setUp(self) -> None:
        from mypy.checkexpr import _set_native_checkexpr_active
        from mypy.wirefixup import set_wire_typeinfo_map

        self.fx = TypeFixture()
        type_infos = []
        for name in dir(self.fx):
            if not name.endswith("i"):
                continue
            value = getattr(self.fx, name)
            if _is_type_info(value):
                type_infos.append(value)
        set_wire_typeinfo_map({info.fullname: info for info in type_infos})
        self._type_infos = type_infos
        self._set_active = _set_native_checkexpr_active
        self._set_active(True)

    def tearDown(self) -> None:
        from mypy.wirefixup import set_wire_typeinfo_map

        self._set_active(False)
        set_wire_typeinfo_map(None)

    def _with_gate(self, active: bool, fn: Callable[[], T]) -> T:
        self._set_active(active)
        try:
            return fn()
        finally:
            self._set_active(True)

    def _assert_par(self, typ: Type) -> None:
        from mypy.checkexpr import try_getting_literal

        off = self._with_gate(False, lambda: try_getting_literal(typ))
        on = self._with_gate(True, lambda: try_getting_literal(typ))
        assert_equal(str(on), str(off), f"try_getting_literal parity {typ}")

    def _assert_engages(self, typ: Type) -> None:
        from mypy.checkexpr import _serialize_type_for_checkexpr

        result = _type_kernel.rust_try_getting_literal(_serialize_type_for_checkexpr(typ))
        assert result is not None, f"Rust try_getting_literal did not engage for {typ}"

    def test_unwraps_last_known_value(self) -> None:
        from mypy.checkexpr import try_getting_literal

        self._assert_par(self.fx.lit_str1_inst)
        result = self._with_gate(True, lambda: try_getting_literal(self.fx.lit_str1_inst))
        assert_equal(str(result), "Literal['x']")
        self._assert_engages(self.fx.lit_str1_inst)

    def test_unwraps_big_int_last_known_value(self) -> None:
        # int(2**80) exceeds i64: the wire long-int encoding must survive
        # both directions of the live seam (issue #1329); the Python shim
        # decodes the Rust-written blob, so this is a full round-trip.
        from mypy.checkexpr import try_getting_literal

        int_type = Instance(self.fx.make_type_info("builtins.int"), [])
        big = 2**80
        inst = Instance(int_type.type, [], last_known_value=LiteralType(big, int_type))
        self._assert_par(inst)
        result = self._with_gate(True, lambda: try_getting_literal(inst))
        assert_equal(str(result), f"Literal[{big}]")
        self._assert_engages(inst)

        neg = -(2**80)
        inst = Instance(int_type.type, [], last_known_value=LiteralType(neg, int_type))
        self._assert_par(inst)
        result = self._with_gate(True, lambda: try_getting_literal(inst))
        assert_equal(str(result), f"Literal[{neg}]")

    def test_plain_instance_unchanged(self) -> None:
        from mypy.checkexpr import try_getting_literal

        plain = Instance(self.fx.ai, [])
        self._assert_par(plain)
        result = self._with_gate(True, lambda: try_getting_literal(plain))
        assert_equal(str(result), "A")
        self._assert_engages(plain)

    def test_none(self) -> None:
        self._assert_par(self.fx.nonet)
        self._assert_engages(self.fx.nonet)

    def test_any(self) -> None:
        self._assert_par(self.fx.anyt)
        self._assert_engages(self.fx.anyt)

    def test_union(self) -> None:
        # `get_proper_type` on a Union is a no-op; the Instance-with-lkv
        # item is not unwrapped (only the root is checked). Parity holds.
        u = UnionType([self.fx.lit_str1_inst, self.fx.a])
        self._assert_par(u)
        self._assert_engages(u)

    def test_uninhabited(self) -> None:
        self._assert_par(self.fx.uninhabited)
        self._assert_engages(self.fx.uninhabited)


@skipUnless(_NATIVE_WIRE_ENABLED, "requires TEST_NATIVE_TYPE_KERNEL=1 and type_kernel ext")
class NativeRevealImportedSuite(Suite):
    """Parity for `rust_classify_reveal_imported` (issue #918).

    `check_reveal_imported` (checkexpr.py:6485-6513) dispatches the
    unimported-reveal error: disabled code -> nothing;
    REVEAL_LOCALS -> "reveal_locals"; REVEAL_TYPE and not is_imported ->
    "reveal_type"; else -> nothing. The Rust seam classifies the whole
    dispatch head from scalar facts and returns the name (or None for
    "do nothing"); Python applies the fail + note side effects. The
    direct seam call must match the expected name/None, and toggling the
    checkexpr gate off vs on must produce identical captured messages.
    """

    def setUp(self) -> None:
        from mypy.checkexpr import _set_native_checkexpr_active

        self._set_active = _set_native_checkexpr_active
        self._set_active(True)

    def tearDown(self) -> None:
        self._set_active(False)

    def _with_gate(self, active: bool, fn: Callable[[], T]) -> T:
        self._set_active(active)
        try:
            return fn()
        finally:
            self._set_active(True)

    def _make_checker(self, code_enabled: bool = True) -> ExpressionChecker:
        from mypy.checker import TypeChecker
        from mypy.checkexpr import ExpressionChecker
        from mypy.errors import Errors
        from mypy.messages import MessageBuilder
        from mypy.nodes import MypyFile, SymbolTable
        from mypy.plugin import Plugin

        options = Options()
        from mypy import errorcodes as codes

        if code_enabled:
            options.enabled_error_codes = {codes.UNIMPORTED_REVEAL}
        errors = Errors(options)
        tree = MypyFile([], [])
        tree.is_stub = True
        tree.names = SymbolTable()
        modules: dict[str, MypyFile] = {}
        chk = TypeChecker(errors, modules, options, tree, "", Plugin(options), {})
        msg = MessageBuilder(errors, modules)
        return ExpressionChecker(chk, msg, Plugin(options), {})

    def _reveal(self, kind: int, is_imported: bool) -> RevealExpr:
        return RevealExpr(kind=kind, is_imported=is_imported)

    def _run_and_capture(
        self, expr: RevealExpr, active: bool, code_enabled: bool = True
    ) -> list[tuple[str, str]]:
        ec = self._make_checker(code_enabled)
        captured: list[tuple[str, str]] = []
        ec.chk.fail = lambda msg, ctx, code=None: captured.append(("fail", msg))  # type: ignore[method-assign, misc, assignment]
        ec.chk.note = lambda msg, ctx, offset=0, code=None: captured.append(("note", msg))  # type: ignore[method-assign, misc]
        self._with_gate(active, lambda: ec.check_reveal_imported(expr))
        return captured

    def _assert_seam(
        self, kind: int, is_imported: bool, enabled: bool, expected: str | None
    ) -> None:
        result = _type_kernel.rust_classify_reveal_imported(kind, is_imported, enabled)
        assert (
            result == expected
        ), f"seam({kind}, {is_imported}, {enabled}) = {result!r}, want {expected!r}"

    def test_seam_disabled(self) -> None:
        from mypy.nodes import REVEAL_LOCALS, REVEAL_TYPE

        self._assert_seam(REVEAL_LOCALS, False, False, None)
        self._assert_seam(REVEAL_TYPE, False, False, None)
        self._assert_seam(REVEAL_TYPE, True, False, None)

    def test_seam_reveal_locals(self) -> None:
        from mypy.nodes import REVEAL_LOCALS

        self._assert_seam(REVEAL_LOCALS, False, True, "reveal_locals")
        # is_imported is irrelevant for reveal_locals.
        self._assert_seam(REVEAL_LOCALS, True, True, "reveal_locals")

    def test_seam_reveal_type_not_imported(self) -> None:
        from mypy.nodes import REVEAL_TYPE

        self._assert_seam(REVEAL_TYPE, False, True, "reveal_type")

    def test_seam_reveal_type_imported(self) -> None:
        from mypy.nodes import REVEAL_TYPE

        self._assert_seam(REVEAL_TYPE, True, True, None)

    def test_seam_unknown_kind(self) -> None:
        self._assert_seam(999, False, True, None)

    def test_par_disabled_emits_nothing(self) -> None:
        from mypy.nodes import REVEAL_LOCALS, REVEAL_TYPE

        for kind, imp in [
            (REVEAL_LOCALS, False),
            (REVEAL_TYPE, False),
            (REVEAL_TYPE, True),
            (999, False),
        ]:
            expr = self._reveal(kind, imp)
            off = self._run_and_capture(expr, False, code_enabled=False)
            on = self._run_and_capture(expr, True, code_enabled=False)
            assert off == on == [], f"disabled kind={kind} imp={imp}: {off}/{on}"

    def test_par_reveal_locals(self) -> None:
        from mypy.nodes import REVEAL_LOCALS

        expr = self._reveal(REVEAL_LOCALS, False)
        off = self._run_and_capture(expr, False)
        on = self._run_and_capture(expr, True)
        assert off == on, f"reveal_locals differential: off={off} on={on}"
        assert off and off[0] == ("fail", 'Name "reveal_locals" is not defined'), off

    def test_par_reveal_type_not_imported(self) -> None:
        from mypy.nodes import REVEAL_TYPE

        expr = self._reveal(REVEAL_TYPE, False)
        off = self._run_and_capture(expr, False)
        on = self._run_and_capture(expr, True)
        assert off == on, f"reveal_type differential: off={off} on={on}"
        assert off and off[0][0] == "fail" and "reveal_type" in off[0][1], off
        assert any(tag == "note" and "typing" in msg for tag, msg in off), off

    def test_par_reveal_type_imported_emits_nothing(self) -> None:
        from mypy.nodes import REVEAL_TYPE

        expr = self._reveal(REVEAL_TYPE, True)
        off = self._run_and_capture(expr, False)
        on = self._run_and_capture(expr, True)
        assert off == on == [], f"imported reveal_type must emit nothing: {off}/{on}"


@skipUnless(_NATIVE_WIRE_ENABLED, "requires TEST_NATIVE_TYPE_KERNEL=1 and type_kernel ext")
class NativeSuperArgTypesSuite(Suite):
    """Parity for `rust_classify_super_arg_types` (issue #956).

    `_super_arg_types` (checkexpr.py:7440) dispatches a stage-1 arity +
    scope gate chain producing 7 early-error returns and 2 fall-through
    bodies. The Rust seam classifies the whole dispatch head from live
    checker/super-expr facts and returns a branch tag; Python applies
    the `self.fail` / `fill_typevars` / `accept` side effects and stage 2
    (proper-type dispatch). The direct seam call must match the expected
    tag for all 9 branches, and toggling the checkexpr gate off vs on
    must produce identical results + captured messages for the 7
    early-exit branches.
    """

    def setUp(self) -> None:
        from mypy.checkexpr import _set_native_checkexpr_active

        self._set_active = _set_native_checkexpr_active
        self._set_active(True)

    def tearDown(self) -> None:
        self._set_active(False)

    def _with_gate(self, active: bool, fn: Callable[[], T]) -> T:
        self._set_active(active)
        try:
            return fn()
        finally:
            self._set_active(True)

    def _make_super_expr(
        self, n_args: int, arg_kinds: list[ArgKind], info: object = None
    ) -> SuperExpr:
        from mypy.nodes import SuperExpr

        args: list[Expression] = [NameExpr(f"a{i}") for i in range(n_args)]
        call = CallExpr(
            callee=NameExpr("super"),
            args=args,
            arg_kinds=list(arg_kinds),
            arg_names=[None] * n_args,
        )
        e = SuperExpr("super", call)
        # Some direct-seam tests pass an opaque object on purpose (the Rust
        # classifier must tolerate unreadable info facts and defer).
        e.info = info  # type: ignore[assignment]
        return e

    def _make_chk(self, in_checked: bool = True, active_class: object = None) -> SimpleNamespace:
        captured: list[tuple[str, str]] = []
        chk = SimpleNamespace(
            in_checked_function=lambda: in_checked,
            fail=lambda msg, ctx, code=None: captured.append(("fail", str(msg))),
            scope=SimpleNamespace(active_class=lambda: active_class),
        )
        chk.captured = captured
        return chk

    def _run_super(
        self, e: SuperExpr, chk: SimpleNamespace, active: bool
    ) -> tuple[str, list[str]]:
        from mypy.checkexpr import ExpressionChecker

        ec = ExpressionChecker.__new__(ExpressionChecker)
        ec.chk = chk  # type: ignore[assignment]
        try:
            result = self._with_gate(active, lambda: ec._super_arg_types(e))
            return (str(result), [m for _, m in chk.captured])
        except Exception as exc:
            return ("EXC:" + str(exc), [m for _, m in chk.captured])

    # -- direct seam tests (all 9 tags) --

    def test_seam_not_checked(self) -> None:
        from mypy.checkexpr import NATIVE_SUPER_ARG_NOT_CHECKED

        e = self._make_super_expr(2, [ARG_POS, ARG_POS], info=object())
        chk = self._make_chk(in_checked=False, active_class=None)
        tag = _type_kernel.rust_classify_super_arg_types(chk, e)
        assert tag == NATIVE_SUPER_ARG_NOT_CHECKED, f"{tag} != {NATIVE_SUPER_ARG_NOT_CHECKED}"

    def test_seam_zero_arg_no_info(self) -> None:
        from mypy.checkexpr import NATIVE_SUPER_ARG_ZERO_ARG_NO_INFO

        e = self._make_super_expr(0, [], info=None)
        chk = self._make_chk(in_checked=True, active_class=None)
        tag = _type_kernel.rust_classify_super_arg_types(chk, e)
        assert tag == NATIVE_SUPER_ARG_ZERO_ARG_NO_INFO, f"{tag}"

    def test_seam_zero_arg_outside_method(self) -> None:
        from mypy.checkexpr import NATIVE_SUPER_ARG_ZERO_ARG_OUTSIDE_METHOD

        e = self._make_super_expr(0, [], info=object())
        chk = self._make_chk(in_checked=True, active_class=object())
        tag = _type_kernel.rust_classify_super_arg_types(chk, e)
        assert tag == NATIVE_SUPER_ARG_ZERO_ARG_OUTSIDE_METHOD, f"{tag}"

    def test_seam_zero_arg_ok(self) -> None:
        from mypy.checkexpr import NATIVE_SUPER_ARG_ZERO_ARG_OK

        e = self._make_super_expr(0, [], info=object())
        chk = self._make_chk(in_checked=True, active_class=None)
        tag = _type_kernel.rust_classify_super_arg_types(chk, e)
        assert tag == NATIVE_SUPER_ARG_ZERO_ARG_OK, f"{tag}"

    def test_seam_varargs(self) -> None:
        from mypy.checkexpr import NATIVE_SUPER_ARG_VARARGS

        e = self._make_super_expr(1, [ARG_STAR], info=object())
        chk = self._make_chk(in_checked=True, active_class=None)
        tag = _type_kernel.rust_classify_super_arg_types(chk, e)
        assert tag == NATIVE_SUPER_ARG_VARARGS, f"{tag}"

    def test_seam_non_positional(self) -> None:
        from mypy.checkexpr import NATIVE_SUPER_ARG_NON_POSITIONAL

        e = self._make_super_expr(1, [ARG_NAMED], info=object())
        chk = self._make_chk(in_checked=True, active_class=None)
        tag = _type_kernel.rust_classify_super_arg_types(chk, e)
        assert tag == NATIVE_SUPER_ARG_NON_POSITIONAL, f"{tag}"

    def test_seam_single_arg(self) -> None:
        from mypy.checkexpr import NATIVE_SUPER_ARG_SINGLE_ARG

        e = self._make_super_expr(1, [ARG_POS], info=object())
        chk = self._make_chk(in_checked=True, active_class=None)
        tag = _type_kernel.rust_classify_super_arg_types(chk, e)
        assert tag == NATIVE_SUPER_ARG_SINGLE_ARG, f"{tag}"

    def test_seam_two_arg_ok(self) -> None:
        from mypy.checkexpr import NATIVE_SUPER_ARG_TWO_ARG_OK

        e = self._make_super_expr(2, [ARG_POS, ARG_POS], info=object())
        chk = self._make_chk(in_checked=True, active_class=None)
        tag = _type_kernel.rust_classify_super_arg_types(chk, e)
        assert tag == NATIVE_SUPER_ARG_TWO_ARG_OK, f"{tag}"

    def test_seam_too_many(self) -> None:
        from mypy.checkexpr import NATIVE_SUPER_ARG_TOO_MANY

        e = self._make_super_expr(3, [ARG_POS, ARG_POS, ARG_POS], info=object())
        chk = self._make_chk(in_checked=True, active_class=None)
        tag = _type_kernel.rust_classify_super_arg_types(chk, e)
        assert tag == NATIVE_SUPER_ARG_TOO_MANY, f"{tag}"

    # -- gate off/on differential tests (7 early-exit branches) --

    def test_par_not_checked(self) -> None:
        e = self._make_super_expr(2, [ARG_POS, ARG_POS], info=object())
        chk = self._make_chk(in_checked=False, active_class=None)
        off = self._run_super(e, chk, False)
        chk2 = self._make_chk(in_checked=False, active_class=None)
        on = self._run_super(e, chk2, True)
        assert off == on, f"not_checked: off={off} on={on}"

    def test_par_zero_arg_no_info(self) -> None:
        e = self._make_super_expr(0, [], info=None)
        chk = self._make_chk(in_checked=True, active_class=None)
        off = self._run_super(e, chk, False)
        chk2 = self._make_chk(in_checked=True, active_class=None)
        on = self._run_super(e, chk2, True)
        assert off == on, f"zero_arg_no_info: off={off} on={on}"

    def test_par_zero_arg_outside_method(self) -> None:
        e = self._make_super_expr(0, [], info=object())
        chk = self._make_chk(in_checked=True, active_class=object())
        off = self._run_super(e, chk, False)
        chk2 = self._make_chk(in_checked=True, active_class=object())
        on = self._run_super(e, chk2, True)
        assert off == on, f"outside_method: off={off} on={on}"
        assert off[1], f"expected fail: {off}"

    def test_par_varargs(self) -> None:
        e = self._make_super_expr(1, [ARG_STAR], info=object())
        chk = self._make_chk(in_checked=True, active_class=None)
        off = self._run_super(e, chk, False)
        chk2 = self._make_chk(in_checked=True, active_class=None)
        on = self._run_super(e, chk2, True)
        assert off == on, f"varargs: off={off} on={on}"
        assert off[1], f"expected fail: {off}"

    def test_par_non_positional(self) -> None:
        e = self._make_super_expr(1, [ARG_NAMED], info=object())
        chk = self._make_chk(in_checked=True, active_class=None)
        off = self._run_super(e, chk, False)
        chk2 = self._make_chk(in_checked=True, active_class=None)
        on = self._run_super(e, chk2, True)
        assert off == on, f"non_positional: off={off} on={on}"
        assert off[1], f"expected fail: {off}"

    def test_par_single_arg(self) -> None:
        e = self._make_super_expr(1, [ARG_POS], info=object())
        chk = self._make_chk(in_checked=True, active_class=None)
        off = self._run_super(e, chk, False)
        chk2 = self._make_chk(in_checked=True, active_class=None)
        on = self._run_super(e, chk2, True)
        assert off == on, f"single_arg: off={off} on={on}"
        assert off[1], f"expected fail: {off}"

    def test_par_too_many(self) -> None:
        e = self._make_super_expr(3, [ARG_POS, ARG_POS, ARG_POS], info=object())
        chk = self._make_chk(in_checked=True, active_class=None)
        off = self._run_super(e, chk, False)
        chk2 = self._make_chk(in_checked=True, active_class=None)
        on = self._run_super(e, chk2, True)
        assert off == on, f"too_many: off={off} on={on}"
        assert off[1], f"expected fail: {off}"


@skipUnless(_NATIVE_WIRE_ENABLED, "requires TEST_NATIVE_TYPE_KERNEL=1 and type_kernel ext")
class NativeInferArgContextSuite(Suite):
    """Parity for `rust_compute_arg_context_indices` (issue #1064).

    `infer_arg_types_in_context` (checkexpr.py:3265) first precomputes the
    pure arg_context index map (formal index per actual, star args
    skipped); the per-arg accept recursion and the infer_unions toggle
    stay in Python. The Rust seam decides from scalars only. Direct seam
    calls assert the mapping (star-skip, empty formal_to_actual,
    no-context tail, malformed deferral); gate off vs on must produce
    identical accept traces across the 3 call-site shapes
    (checkexpr.py:3004, 3424, 3627).
    """

    def setUp(self) -> None:
        from mypy.checkexpr import _set_native_checkexpr_active

        self._set_active = _set_native_checkexpr_active
        self._set_active(True)
        self.fx = TypeFixture()

    def tearDown(self) -> None:
        self._set_active(False)

    def _with_gate(self, active: bool, fn: Callable[[], T]) -> T:
        self._set_active(active)
        try:
            return fn()
        finally:
            self._set_active(True)

    def _make_callee(self, n_args: int) -> CallableType:
        return CallableType(
            [AnyType(TypeOfAny.special_form)] * n_args,
            [ARG_POS] * n_args,
            [None] * n_args,
            AnyType(TypeOfAny.special_form),
            self.fx.function,
        )

    # -- direct seam tests --

    def test_seam_star_skip(self) -> None:
        out = _type_kernel.rust_compute_arg_context_indices(
            [ARG_POS.value, ARG_STAR.value, ARG_STAR2.value, ARG_POS.value], [[0, 1, 2, 3]], 4, 1
        )
        assert out == [0, -1, -1, 0], f"{out}"

    def test_seam_empty_formal_to_actual(self) -> None:
        out = _type_kernel.rust_compute_arg_context_indices([ARG_POS.value] * 2, [], 2, 1)
        assert out == [-1, -1], f"{out}"

    def test_seam_no_context_tail(self) -> None:
        out = _type_kernel.rust_compute_arg_context_indices([ARG_POS.value] * 3, [[1]], 3, 1)
        assert out == [-1, 0, -1], f"{out}"

    def test_seam_malformed_defers(self) -> None:
        # Actual index out of bounds of args_len.
        out = _type_kernel.rust_compute_arg_context_indices([0, 0], [[2]], 2, 1)
        assert out is None, f"{out}"
        # Formal index out of bounds of callee.arg_types.
        out = _type_kernel.rust_compute_arg_context_indices([0, 0], [[0], [1]], 2, 1)
        assert out is None, f"{out}"
        # arg_kinds / args_len mismatch.
        out = _type_kernel.rust_compute_arg_context_indices([0], [[0]], 2, 1)
        assert out is None, f"{out}"

    # -- gate off/on differential across the 3 call sites --

    def _run_infer(
        self,
        callee: CallableType,
        args: list[Expression],
        arg_kinds: list[ArgKind],
        formal_to_actual: list[list[int]],
        active: bool,
    ) -> list[str]:
        from mypy.checkexpr import ExpressionChecker

        captured: list[str] = []
        ec = ExpressionChecker.__new__(ExpressionChecker)

        def accept(arg: Expression, ctx: Type | None = None) -> Any:
            captured.append(f"{arg!r}|ctx={ctx!r}")
            return arg

        ec.accept = accept  # type: ignore[assignment]
        result = self._with_gate(
            active,
            lambda: ec.infer_arg_types_in_context(callee, args, arg_kinds, formal_to_actual),
        )
        return [str(r) for r in result] + captured

    def _make_args(self, n: int) -> list[Expression]:
        return [NameExpr(f"a{i}") for i in range(n)]

    def test_par_lambda_body_site(self) -> None:
        # checkexpr.py:3004 shape: positional args, 1:1 formal mapping.
        callee = self._make_callee(2)
        args = self._make_args(2)
        kinds = [ARG_POS, ARG_POS]
        f2a = [[0], [1]]
        off = self._run_infer(callee, args, kinds, f2a, False)
        on = self._run_infer(callee, args, kinds, f2a, True)
        assert off == on, f"lambda_body: off={off} on={on}"
        assert all("ctx=Any" in s for s in on[len(args) :]), f"expected contexts: {on}"

    def test_par_first_pass_site(self) -> None:
        # checkexpr.py:3424 shape: optional + named formals, error-filtered.
        callee = self._make_callee(3)
        args = self._make_args(3)
        kinds = [ARG_POS, ARG_OPT, ARG_NAMED]
        f2a = [[0], [1], [2]]
        off = self._run_infer(callee, args, kinds, f2a, False)
        on = self._run_infer(callee, args, kinds, f2a, True)
        assert off == on, f"first_pass: off={off} on={on}"

    def test_par_second_pass_site(self) -> None:
        # checkexpr.py:3627 shape: star args skipped, kwargs shares a formal.
        callee = self._make_callee(2)
        args = self._make_args(3)
        kinds = [ARG_POS, ARG_STAR, ARG_STAR2]
        f2a = [[0, 1, 2], [2]]
        off = self._run_infer(callee, args, kinds, f2a, False)
        on = self._run_infer(callee, args, kinds, f2a, True)
        assert off == on, f"second_pass: off={off} on={on}"
        assert "ctx=None" in on[len(args) + 1], f"star arg must have no context: {on}"

    def test_par_no_context_all(self) -> None:
        # Empty formal_to_actual: every actual accepted without context.
        callee = self._make_callee(2)
        args = self._make_args(2)
        kinds = [ARG_POS, ARG_POS]
        off = self._run_infer(callee, args, kinds, [], False)
        on = self._run_infer(callee, args, kinds, [], True)
        assert off == on, f"no_context: off={off} on={on}"
        assert all("ctx=None" in s for s in on[len(args) :]), f"{on}"


@skipUnless(_NATIVE_WIRE_ENABLED, "requires TEST_NATIVE_TYPE_KERNEL=1 and type_kernel ext")
class NativeVisitOpExprSuite(Suite):
    """Parity for `rust_classify_visit_op_expr` (issue #959).

    `ExpressionChecker.visit_op_expr` (checkexpr.py:5014-5044) dispatches a
    5-way branch: `e.analyzed` passthrough, `and`/`or` boolean op,
    `*` with `ListExpr` list multiply, `%` with `BytesExpr`/`StrExpr` str
    interpolation, else `check_op`. The Rust seam classifies the whole
    dispatch head from live `e.analyzed`, `e.op`, and `e.left` isinstance
    facts and returns a branch tag; Python delegates to the original
    branch body. Direct seam calls assert the exact tag for every branch;
    toggling the checkexpr gate off vs on must produce identical results.
    """

    def setUp(self) -> None:
        from mypy.checkexpr import _set_native_checkexpr_active

        self._set_active = _set_native_checkexpr_active
        self._set_active(True)

    def tearDown(self) -> None:
        self._set_active(False)

    def _with_gate(self, active: bool, fn: Callable[[], T]) -> T:
        self._set_active(active)
        try:
            return fn()
        finally:
            self._set_active(True)

    def _tag(self, e: OpExpr) -> int | None:
        return _type_kernel.rust_classify_visit_op_expr(e)

    def test_seam_analyzed_passthrough(self) -> None:
        e = OpExpr("|", NameExpr("X"), NameExpr("Y"))
        e.analyzed = NameExpr("Analyzed")  # type: ignore[assignment]
        assert self._tag(e) == 0

    def test_seam_boolean_and(self) -> None:
        e = OpExpr("and", NameExpr("X"), NameExpr("Y"))
        assert self._tag(e) == 1

    def test_seam_boolean_or(self) -> None:
        e = OpExpr("or", NameExpr("X"), NameExpr("Y"))
        assert self._tag(e) == 1

    def test_seam_list_multiply(self) -> None:
        e = OpExpr("*", ListExpr([]), NameExpr("N"))
        assert self._tag(e) == 2

    def test_seam_str_interp_bytes(self) -> None:
        e = OpExpr("%", BytesExpr("%s"), NameExpr("Y"))
        assert self._tag(e) == 3

    def test_seam_str_interp_str(self) -> None:
        e = OpExpr("%", StrExpr("%s"), NameExpr("Y"))
        assert self._tag(e) == 3

    def test_seam_check_op_default(self) -> None:
        assert self._tag(OpExpr("+", NameExpr("X"), NameExpr("Y"))) == 4
        assert self._tag(OpExpr("|", NameExpr("X"), NameExpr("Y"))) == 4
        assert self._tag(OpExpr("-", NameExpr("X"), NameExpr("Y"))) == 4

    def test_seam_star_not_list(self) -> None:
        e = OpExpr("*", NameExpr("X"), NameExpr("Y"))
        assert self._tag(e) == 4

    def test_seam_percent_not_bytes_str(self) -> None:
        e = OpExpr("%", NameExpr("X"), NameExpr("Y"))
        assert self._tag(e) == 4

    def test_seam_and_overrides_list(self) -> None:
        # "and" takes precedence over isinstance checks.
        e = OpExpr("and", ListExpr([]), NameExpr("Y"))
        assert self._tag(e) == 1

    def test_seam_star_bytes_not_list_multiply(self) -> None:
        # "*" with BytesExpr left goes to check_op, not list multiply.
        e = OpExpr("*", BytesExpr("x"), NameExpr("Y"))
        assert self._tag(e) == 4


@skipUnless(_NATIVE_WIRE_ENABLED, "requires TEST_NATIVE_TYPE_KERNEL=1 and type_kernel ext")
class NativeProtocolImplementationSuite(Suite):
    """Engagement for the `rust_is_protocol_implementation` seam.

    The `_is_subtype` protocol-right fallback (subtypes.py) drives the
    member-compat loop natively when `right.type.is_protocol` and the
    left is a non-protocol Instance: it matches the targets that owned
    the `rust_is_subtype` deferral population (SupportsIndex / Sized /
    SupportsBool / SupportsInt / Awaitable). The deferred path needs a
    live `checker_state.type_checker`, so it cannot be exercised through
    `is_subtype` in unit tests; instead each test calls the seam
    directly, proving engagement and agreement with the pure-Python
    member loop on small synthetic protocols.

    The member-lookup half of the loop runs `get_protocol_member_inner`
    (plain methods bind via `member_method_inner`; plain vars expand via
    `expand_type_by_instance`), and the member pair recurses into the
    native callable engine for method members. Protocols are built with
    `make_type_info`, a `protocol_members`-visible MRO
    (`[info, object]`), `is_protocol=True`, and `names` populated with
    FuncDef/Var members; the live TypeInfo map is passed
    (`set_live_typeinfo_map`) so the member lookups resolve.
    """

    def setUp(self) -> None:
        self.fx = TypeFixture()

    def _protocol(
        self, fullname: str, members: list[str], func_types: dict[str, CallableType] | None = None
    ) -> TypeInfo:
        """Build a protocol TypeInfo with plain-method members.

        Members are `FuncDef`s typed with `func_types` (default a plain
        method with self → the class and return A), which the
        `get_protocol_member_inner` plain-method path binds via
        `member_method_inner`. The MRO must be set for
        `protocol_members` to be readable (nodes.py:4081 asserts MRO).
        """
        from mypy.types import Instance

        info = self.fx.make_type_info(fullname)
        info.mro = [info, self.fx.oi]
        info.is_protocol = True
        inst = Instance(info, [])
        for name in members:
            node = FuncDef(name, [], None, None)
            node.info = info
            node.type = (
                func_types[name]
                if func_types is not None
                else self._method_callable(self.fx.a, inst)
            )
            node.line = 1
            node.column = 1
            info.names[name] = SymbolTableNode(MDEF, node)
        self._live_info[fullname] = info
        return info

    def _impl(
        self, fullname: str, members: list[str], func_types: dict[str, CallableType] | None = None
    ) -> TypeInfo:
        """Build an implementing (non-protocol) Info with typed methods."""
        from mypy.types import Instance

        info = self.fx.make_type_info(fullname)
        info.mro = [info, self.fx.oi]
        inst = Instance(info, [])
        for name in members:
            node = FuncDef(name, [], None, None)
            node.info = info
            node.type = (
                func_types[name]
                if func_types is not None
                else self._method_callable(self.fx.a, inst)
            )
            node.line = 1
            node.column = 1
            info.names[name] = SymbolTableNode(MDEF, node)
        self._live_info[fullname] = info
        return info

    def _method_callable(
        self, ret: Type | None = None, self_type: Type | None = None
    ) -> CallableType:
        from mypy.types import CallableType

        # A plain method has an explicit `self` positional param typed as
        # the defining class (check_self_arg_inner requires a non-empty
        # arg[0]; bind_self strips it after self-compat).
        self_arg = self_type if self_type is not None else self.fx.a
        return CallableType(
            [self_arg], [ARG_POS], [None], ret if ret is not None else self.fx.a, self.fx.function
        )

    def _build_resolver(self) -> None:
        """Build a native resolver over fixture + synthetic infos."""
        from mypy.wirefixup import set_wire_typeinfo_map

        type_infos = []
        for name in dir(self.fx):
            if not name.endswith("i"):
                continue
            value = getattr(self.fx, name)
            if _is_type_info(value):
                type_infos.append(value)
        type_infos.extend(list(self._live_info.values()))
        self.resolver = _type_kernel.build_native_resolver(type_infos, [])
        self.resolver.set_live_typeinfo_map(dict(self._live_info))
        set_wire_typeinfo_map(dict(self._live_info))

    def _serialize(self, typ: Type) -> bytes:
        from mypy.subtypes import _serialize_type

        return _serialize_type(typ)

    def _seam_call(self, left: Type, right: Type, *, proper: bool = False) -> bool | None:
        from mypy.subtypes import _set_native_subtype_active

        _set_native_subtype_active(True)
        try:
            result = _type_kernel.rust_is_protocol_implementation(
                self._serialize(left),
                self._serialize(right),
                [],
                False,  # ignore_type_params
                False,
                False,
                False,
                proper,
                True,  # strict_optional
                False,  # ignore_pos_arg_names
                False,  # strict_concatenate
                self.resolver,
            )
            return result
        finally:
            _set_native_subtype_active(False)

    def _method_with_return(self, info: TypeInfo, ret: Type) -> CallableType:
        from mypy.types import Instance

        return self._method_callable(ret, Instance(info, []))

    def test_single_method_protocol_engages(self) -> None:
        """A simple `__len__`-style protocol must be decided natively."""
        self._live_info: dict[str, TypeInfo] = {}
        # protocol P: def f(self) -> A
        p = self._protocol("mod.P", ["f"])
        # impl I: def f(self) -> A
        i = self._impl("mod.I", ["f"])
        self._build_resolver()
        from mypy.types import Instance

        result = self._seam_call(Instance(i, []), Instance(p, []))
        assert result is True, f"implementing protocol must be True, got {result!r}"

    def test_non_matching_arg_type_returns_false(self) -> None:
        """A method returning object (A's supertype) is not an
        implementation of `f() -> A`."""
        from mypy.types import Instance

        self._live_info = {}
        p = self._protocol("mod.P", ["f"])
        i = self._impl("mod.I", ["f"])
        # f on I returns object; protocol requires A. object is a
        # supertype of A, so the return is not compatible.
        fnode = i.names["f"].node
        assert fnode is not None
        # runtime node is a FuncDef; Var accepted for the Var-member case
        assert isinstance(fnode, (Var, FuncDef))
        fnode.type = self._method_with_return(i, self.fx.o)
        self._build_resolver()
        result = self._seam_call(Instance(i, []), Instance(p, []))
        assert result is False, f"object-returning member must not implement, got {result!r}"

    def test_missing_method_returns_false(self) -> None:
        """Missing method: Rust returns False (not an implementation)."""
        from mypy.types import Instance

        self._live_info = {}
        p = self._protocol("mod.P", ["f"])
        i = self._impl("mod.I", [])
        self._build_resolver()
        result = self._seam_call(Instance(i, []), Instance(p, []))
        assert result is False, f"missing member must be False, got {result!r}"

    def test_protocol_left_symmetric_pair_decides(self) -> None:
        """Protocol-left engages (#1344): a symmetric member-set pair
        with matching member signatures is decided True natively through
        the same member loop Python runs (trivial check, assuming guard,
        flags)."""
        from mypy.types import Instance

        self._live_info = {}
        p1 = self._protocol("mod.P1", ["f"])
        p2 = self._protocol("mod.P2", ["f"])
        self._build_resolver()
        result = self._seam_call(Instance(p1, []), Instance(p2, []))
        assert result is True, f"protocol-left pair must decide natively, got {result!r}"

    def test_non_protocol_right_defers(self) -> None:
        """Non-protocol right must defer (None), matching the assert in
        `is_protocol_implementation` (callers pass protocol rights only)."""
        from mypy.types import Instance

        self._live_info = {}
        i = self._impl("mod.I", ["f"])
        self._build_resolver()
        result = self._seam_call(Instance(i, []), Instance(i, []))
        assert result is None, f"non-protocol right must defer, got {result!r}"

    def test_protocol_left_subset_miss_decides_false(self) -> None:
        """Protocol-left member-set miss decides False natively: the
        subtypes.py:1906-1911 fast path fires only when the LEFT side is
        a protocol, before the assuming scan. The earlier wholesale
        defer was pure caution (a naive right-side-only probe diverged
        under --no-strict-optional, testMeetOfIncompatibleProtocols,
        #1356)."""
        from mypy.types import Instance

        self._live_info = {}
        # left protocol: only `f`; right protocol: requires `f` and `g`.
        p1 = self._protocol("mod.P1", ["f"])
        p2 = self._protocol("mod.P2", ["f", "g"])
        self._build_resolver()
        left, right = Instance(p1, []), Instance(p2, [])
        result = self._seam_call(left, right)
        assert result is False, f"member-set-miss pair must decide False, got {result!r}"

    def test_protocol_left_python_body_agreement(self) -> None:
        """The new native protocol-left decisions must match the
        pure-Python `is_protocol_implementation` body on the same
        fixtures (gate-off Python member loop vs the seam)."""
        from mypy.subtypes import is_protocol_implementation
        from mypy.types import Instance

        self._live_info = {}
        p1 = self._protocol("mod.P1", ["f"])
        p2 = self._protocol("mod.P2", ["f"])
        p3 = self._protocol("mod.P3", ["f"])
        p4 = self._protocol("mod.P4", ["f", "g"])
        # mismatched-ret pair: left f -> object, right f -> A
        p5 = self._protocol("mod.P5", ["f"])
        fnode = p5.names["f"].node
        assert isinstance(fnode, FuncDef)
        fnode.type = self._method_with_return(p5, self.fx.o)
        p6 = self._protocol("mod.P6", ["f"])
        self._build_resolver()
        for left, right, expected in [
            (Instance(p1, []), Instance(p2, []), True),
            (Instance(p3, []), Instance(p4, []), False),
            (Instance(p5, []), Instance(p6, []), False),
        ]:
            py_result = is_protocol_implementation(left, right)
            rust_result = self._seam_call(left, right)
            assert py_result == expected == rust_result, (expected, py_result, rust_result)

    def test_protocol_left_registry_cut(self) -> None:
        """A pair registered in flight on the Python side cuts the
        native protocol-left check to True exactly where the `assuming`
        matrix scan would, even though the member loop itself would
        decide False (the cut carries Python's coinductive recursion
        semantics across the defer boundary, #1344)."""
        from mypy.subtypes import _PROTOCOL_PAIRS_IN_FLIGHT, _serialize_type
        from mypy.types import Instance

        self._live_info = {}
        p1 = self._protocol("mod.P1", ["f"])
        p2 = self._protocol("mod.P2", ["f"])
        # left f -> object vs right f -> A: the member loop alone says False.
        fnode = p1.names["f"].node
        assert isinstance(fnode, FuncDef)
        fnode.type = self._method_with_return(p1, self.fx.o)
        self._build_resolver()
        left, right = Instance(p1, []), Instance(p2, [])
        key = (_serialize_type(left), _serialize_type(right), False)
        assert key not in _PROTOCOL_PAIRS_IN_FLIGHT
        _PROTOCOL_PAIRS_IN_FLIGHT[key] = 1
        try:
            result = self._seam_call(left, right)
        finally:
            assert _PROTOCOL_PAIRS_IN_FLIGHT[key] == 1, "seam must not touch the registry"
            del _PROTOCOL_PAIRS_IN_FLIGHT[key]
        assert result is True, f"in-flight pair must cut True, got {result!r}"

    def test_flush_returns_but_never_caches_cut_answers(self) -> None:
        """A true answer sampled through a registry-consult cut is correct
        only for the derivation that took the cut: `_flush_subtype_batch`
        must hand it to the triggering call but never persist it into
        `_subtype_answers`. Without this, a later fresh derivation of the
        same pair reads the poisoned True cache
        (testProtocolIncompatibilityWithUnionType, batch poisoning)."""
        import mypy.subtypes as subtypes_mod
        from mypy.subtypes import (
            _PROTOCOL_PAIRS_IN_FLIGHT,
            _clear_subtype_batch,
            _set_native_subtype_active,
            _set_native_subtype_resolver,
        )
        from mypy.types import Instance

        self._live_info = {}
        # left f -> object vs right f -> A: the member loop alone says
        # False, so a True answer can only come from the consult cut.
        p1 = self._protocol("mod.FlushCutP1", ["f"])
        p2 = self._protocol("mod.FlushCutP2", ["f"])
        fnode = p1.names["f"].node
        assert isinstance(fnode, FuncDef)
        fnode.type = self._method_with_return(p1, self.fx.o)
        self._build_resolver()
        _set_native_subtype_active(True)
        _set_native_subtype_resolver(self.resolver)
        left, right = Instance(p1, []), Instance(p2, [])
        left_b, right_b = self._serialize(left), self._serialize(right)
        ctx_key = (False, False, False, False, False, True, False, False, False)
        pair_key = (left_b, right_b, False)
        assert pair_key not in _PROTOCOL_PAIRS_IN_FLIGHT
        _PROTOCOL_PAIRS_IN_FLIGHT[pair_key] = 1
        flushed_key = (left_b, right_b, ctx_key)
        try:
            _clear_subtype_batch()
            # Sibling pair (any instance <: object) rides the same batch;
            # its code-1 answer must still be cached.
            sibling = (self._serialize(right), self._serialize(Instance(self.fx.oi, [])), ctx_key)
            subtypes_mod._subtype_batch.append((left_b, right_b, ctx_key))
            subtypes_mod._subtype_batch.append(sibling)
            answers = subtypes_mod._flush_subtype_batch()
            assert (
                answers.get(flushed_key) is True
            ), f"cut answer must reach the caller: {answers!r}"
            # (_clear_subtype_batch wipes _subtype_answers too, so every
            # cache assertion must run before the cleanup.)
            assert (
                flushed_key not in subtypes_mod._subtype_answers
            ), "cut answer must not persist into _subtype_answers"
            assert (
                sibling in subtypes_mod._subtype_answers
                and subtypes_mod._subtype_answers[sibling] is True
            ), "plain decided pair must still cache"
            assert (
                _PROTOCOL_PAIRS_IN_FLIGHT.get(pair_key) == 1
            ), "flush must not touch the registry"
        finally:
            _PROTOCOL_PAIRS_IN_FLIGHT.pop(pair_key, None)
            _clear_subtype_batch()
            _set_native_subtype_active(False)
            _set_native_subtype_resolver(None)

    def test_flush_fresh_derivation_runs_member_loop(self) -> None:
        """End-to-end poisoning pin: after a consult-cut `True` has been
        flushed for an in-flight pair, a later flush of the identical
        bytes under the same flags (registry now empty) must NOT be
        answered True from any cache; its slot defers so Python re-derives
        via the single-pair path and the member loop decides."""
        import mypy.subtypes as subtypes_mod
        from mypy.subtypes import (
            _PROTOCOL_PAIRS_IN_FLIGHT,
            _clear_subtype_batch,
            _flush_subtype_batch,
            _set_native_subtype_active,
            _set_native_subtype_resolver,
        )
        from mypy.types import Instance

        self._live_info = {}
        p1 = self._protocol("mod.FreshCutP1", ["f"])
        p2 = self._protocol("mod.FreshCutP2", ["f"])
        fnode = p1.names["f"].node
        assert isinstance(fnode, FuncDef)
        fnode.type = self._method_with_return(p1, self.fx.o)
        self._build_resolver()
        _set_native_subtype_active(True)
        _set_native_subtype_resolver(self.resolver)
        left, right = Instance(p1, []), Instance(p2, [])
        left_b, right_b = self._serialize(left), self._serialize(right)
        ctx_key = (False, False, False, False, False, True, False, False, False)
        pair_key = (left_b, right_b, False)
        try:
            _clear_subtype_batch()
            _PROTOCOL_PAIRS_IN_FLIGHT[pair_key] = 1
            try:
                subtypes_mod._subtype_batch.append((left_b, right_b, ctx_key))
                answers = _flush_subtype_batch()
            finally:
                del _PROTOCOL_PAIRS_IN_FLIGHT[pair_key]
            # The cut answer reaches the first derivation...
            assert answers.get((left_b, right_b, ctx_key)) is True
            # ...and the second derivation of the identical pair must not
            # see a cached True: a fresh flush (registry empty) must
            # re-derive and answer False instead.
            subtypes_mod._subtype_batch.append((left_b, right_b, ctx_key))
            second = _flush_subtype_batch()
            assert (
                second.get((left_b, right_b, ctx_key)) is False
            ), f"poisoned cache re-answered cut True without re-derivation: {second!r}"
        finally:
            _clear_subtype_batch()
            _set_native_subtype_active(False)
            _set_native_subtype_resolver(None)

    def test_protocol_left_defers_on_undecidable_member(self) -> None:
        """Protocol-left still defers when a member fetch cannot decide
        (here a @staticmethod member, whose analyze_var shape the bind
        tail cannot mirror; same defer closure as
        NativeProtocolMemberDeferSuite)."""
        from mypy.nodes import Block, Decorator, FuncDef, Var
        from mypy.types import CallableType, Instance

        self._live_info = {}
        p1 = self._protocol("mod.P1", ["f"])
        p2 = self._protocol("mod.P2", ["f"])
        fd = FuncDef("f", [], Block([]))
        fd.info = p2
        v = Var("f")
        v.info = p2
        v.is_staticmethod = True
        v.is_initialized_in_class = True
        v.is_ready = True
        v.is_inferred = False
        v.type = CallableType([Instance(p2, [])], [ARG_POS], [None], self.fx.a, self.fx.function)
        p2.names["f"] = SymbolTableNode(MDEF, Decorator(fd, [], v))
        self._build_resolver()
        result = self._seam_call(Instance(p1, []), Instance(p2, []))
        assert result is None, f"undecidable member fetch must defer, got {result!r}"


@skipUnless(_NATIVE_WIRE_ENABLED, "requires TEST_NATIVE_TYPE_KERNEL=1 and type_kernel ext")
class NativeProtocolMemberDeferSuite(Suite):
    """Engagement for the `get_protocol_member_inner` defer closures
    ported in issue #1121.

    The protocol-right member loop (is_protocol_implementation_inner)
    previously went back to Python whenever the looked-up member was a
    Decorator node (typeshed `@property` protocol members like
    ``SupportsIndex.__index__`` / ``Sized.__len__``) or was defined on a
    base class of the receiver (the same-class guard of
    member_method_inner). Both shapes are now decided natively:

    * Decorator nodes unwrap to ``.var``; the var's callable type runs
      the same bind + map + expand tail as a plain method, and a property
      member yields the getter's return type (checkmember.py:1966-1982).
      Static methods still defer (analyze_var skips the self bind for
      them, which member_method_inner's strip would get wrong).
    * Base-class-defined members run the same tail with the
      allow_subclass_receiver flag; `map_instance_to_supertype` re-maps
      the receiver to the defining class (the pure-Python
      `analyze_instance_member_access` maps via `method.info`).

    Each test calls the `rust_is_protocol_implementation` seam directly
    (the deferred path needs a live checker_state, mirroring
    NativeProtocolImplementationSuite) and asserts the decided answer.
    """

    def setUp(self) -> None:
        from mypy.checkexpr import _set_native_plugin_hook_registry
        from mypy.options import Options
        from mypy.plugins.default import DEFAULT_HOOK_FULLNAMES_BY_KIND, DefaultPlugin

        self.fx = TypeFixture()
        self._live_info: dict[str, Any] = {}
        self.resolver: Any = None
        # The decorator arm resolves attribute hooks through the live
        # ChainedPlugin snapshot; install a defaults-only chain so the
        # synthetic member fullnames are provably unhooked.
        import type_kernel as _type_kernel

        registry = _type_kernel.PluginHookRegistry(
            {kind: list(names) for kind, names in DEFAULT_HOOK_FULLNAMES_BY_KIND.items()}
        )
        _set_native_plugin_hook_registry(registry, False, [DefaultPlugin(Options())])

    def tearDown(self) -> None:
        from mypy.checkexpr import _set_native_plugin_hook_registry

        _set_native_plugin_hook_registry(None, False)

    def _protocol_info(self, fullname: str) -> Any:
        """Build and register a protocol TypeInfo (plain MRO)."""
        info = self.fx.make_type_info(fullname)
        info.mro = [info, self.fx.oi]
        info.is_protocol = True
        self._live_info[fullname] = info
        return info

    def _impl_info(self, fullname: str) -> Any:
        """Build and register a non-protocol TypeInfo (plain MRO)."""
        info = self.fx.make_type_info(fullname)
        info.mro = [info, self.fx.oi]
        self._live_info[fullname] = info
        return info

    def _property_decorator(self, name: str, ret_type: Any, owner: Any) -> Any:
        """A ``@property def name(self) -> ret`` Decorator node owned by
        `owner`, with the getter bound against the owner's instance."""
        from mypy.nodes import Block, Decorator, FuncDef, Var
        from mypy.types import CallableType, Instance

        fd = FuncDef(name, [], Block([]))
        fd.info = owner
        v = Var(name)
        v.info = owner
        v.is_property = True
        v.is_initialized_in_class = True
        v.is_ready = True
        v.is_inferred = False
        v.type = CallableType([Instance(owner, [])], [ARG_POS], [None], ret_type, self.fx.function)
        return Decorator(fd, [], v)

    def _staticmethod_decorator(self, name: str, ret_type: Any, owner: Any) -> Any:
        """A ``@staticmethod def name(...) -> ret`` Decorator node."""
        from mypy.nodes import Block, Decorator, FuncDef, Var
        from mypy.types import CallableType

        fd = FuncDef(name, [], Block([]))
        fd.info = owner
        v = Var(name)
        v.info = owner
        v.is_staticmethod = True
        v.is_initialized_in_class = True
        v.is_ready = True
        v.is_inferred = False
        v.type = CallableType([self.fx.a], [ARG_POS], [None], ret_type, self.fx.function)
        return Decorator(fd, [], v)

    def _method_callable(self, ret: Any, self_type: Any) -> Any:
        from mypy.types import CallableType

        return CallableType([self_type], [ARG_POS], [None], ret, self.fx.function)

    def _base_impl(self, fullname: str, base: Any, member: str, func_types: dict[str, Any]) -> Any:
        """An implementing Info that inherits `member` from `base`."""
        from mypy.types import Instance

        info = self.fx.make_type_info(fullname)
        base.mro = [base, info, self.fx.oi]
        info.mro = [info, base, self.fx.oi]
        info.bases = [Instance(base, [])]
        node = FuncDef(member, [], None)
        node.info = base
        node.type = func_types[member]
        node.line = 1
        node.column = 1
        base.names[member] = SymbolTableNode(MDEF, node)
        self._live_info[fullname] = info
        self._live_info[base.fullname] = base
        return info

    def _build_resolver(self) -> None:
        from mypy.wirefixup import set_wire_typeinfo_map

        type_infos = []
        for name in dir(self.fx):
            if not name.endswith("i"):
                continue
            value = getattr(self.fx, name)
            if _is_type_info(value):
                type_infos.append(value)
        type_infos.extend(list(self._live_info.values()))
        self.resolver = _type_kernel.build_native_resolver(type_infos, [])
        self.resolver.set_live_typeinfo_map(dict(self._live_info))
        set_wire_typeinfo_map(dict(self._live_info))

    def _seam_call(self, left: Any, right: Any) -> bool | None:
        from mypy.subtypes import _serialize_type

        return _type_kernel.rust_is_protocol_implementation(
            _serialize_type(left),
            _serialize_type(right),
            [],
            False,
            False,
            False,
            False,
            False,  # proper_subtype
            True,  # strict_optional
            False,
            False,
            self.resolver,
        )

    def test_property_protocol_member_engages(self) -> None:
        """A protocol whose member is a `@property` Decorator (the
        ``Sized.__len__`` shape) must be decided natively: the sup lookup
        unwraps to the getter and compares its return type against the
        implementation's property value."""
        from mypy.types import Instance

        self._live_info = {}
        p_info = self._protocol_info("mod.P")
        i_info = self._impl_info("mod.I")
        p_info.names["attr"] = SymbolTableNode(
            MDEF, self._property_decorator("attr", self.fx.a, p_info)
        )
        i_info.names["attr"] = SymbolTableNode(
            MDEF, self._property_decorator("attr", self.fx.a, i_info)
        )
        self._build_resolver()
        result = self._seam_call(Instance(i_info, []), Instance(p_info, []))
        assert result is True, f"property-protocol must be decided True, got {result!r}"

    def test_property_protocol_ret_mismatch_false(self) -> None:
        """A property whose getter returns a different type is not an
        implementation: the member VALUE (ret type) is compared, not the
        bound getter callable."""
        from mypy.types import Instance

        self._live_info = {}
        p_info = self._protocol_info("mod.P")
        i_info = self._impl_info("mod.I")
        p_info.names["attr"] = SymbolTableNode(
            MDEF, self._property_decorator("attr", self.fx.a, p_info)
        )
        i_info.names["attr"] = SymbolTableNode(
            MDEF, self._property_decorator("attr", self.fx.o, i_info)
        )
        self._build_resolver()
        result = self._seam_call(Instance(i_info, []), Instance(p_info, []))
        assert result is False, f"wrong-return property must not implement, got {result!r}"

    def test_staticmethod_member_still_defers(self) -> None:
        """A `@staticmethod` member still defers: analyze_var skips the
        self bind for static methods, which the bind tail would get wrong."""
        from mypy.types import Instance

        self._live_info = {}
        p_info = self._protocol_info("mod.P")
        i_info = self._impl_info("mod.I")
        p_info.names["f"] = SymbolTableNode(
            MDEF, self._staticmethod_decorator("f", self.fx.a, p_info)
        )
        i_info.names["f"] = SymbolTableNode(
            MDEF, self._staticmethod_decorator("f", self.fx.a, i_info)
        )
        self._build_resolver()
        result = self._seam_call(Instance(i_info, []), Instance(p_info, []))
        assert result is None, f"staticmethod member must defer, got {result!r}"

    def test_base_class_member_engages(self) -> None:
        """An inherited member (defining class is a base of the receiver)
        must be decided natively: map_instance_to_supertype re-maps the
        receiver to the defining class before the bind."""
        from mypy.types import Instance

        self._live_info = {}
        base = self._impl_info("mod.Base")
        p_info = self._protocol_info("mod.P")
        i = self._base_impl(
            "mod.Sub", base, "f", {"f": self._method_callable(self.fx.a, Instance(base, []))}
        )
        fnode = FuncDef("f", [], None)
        fnode.info = p_info
        fnode.type = self._method_callable(self.fx.a, Instance(p_info, []))
        p_info.names["f"] = SymbolTableNode(MDEF, fnode)
        self._build_resolver()
        result = self._seam_call(Instance(i, []), Instance(p_info, []))
        assert result is True, f"inherited member must be decided True, got {result!r}"


@skipUnless(_NATIVE_WIRE_ENABLED, "requires TEST_NATIVE_TYPE_KERNEL=1 and type_kernel ext")
class NativeAliasExpansionSuite(Suite):
    """Parity suite for TypeAliasType expansion in kernel seams (alias slice).

    Four seams previously deferred to Python on a `TypeAliasType` because
    the wire carries only `type_ref`; each now expands the alias through
    the native resolver's alias snapshot (chain-resolving,
    argument-substituting) and decides:

    - `rust_make_simplified_union` (mypy.typeops) expands alias items
      before the flatten/dedup/contract pipeline, mirroring
      `flatten_nested_unions`' per-item `get_proper_type`.
    - `rust_remove_redundant_union_items` (mypy.typeops) expands each
      item up front, mirroring the Python loop's `get_proper_type(ti)`.
    - `rust_is_duplicate_mapping` (mypy.checkexpr) expands the `**kwargs`
      actuals through `get_proper_or_expand` when checking whether every
      mapped actual is a non-TypedDict `**kwargs`.
    - `rust_type_requires_usage` (mypy.checker) expands the type before
      the `typing.Coroutine` instance dispatch, mirroring
      `get_proper_type(typ)`.

    Each test toggles the owning gate off (pure Python) and on (Rust
    seam) and asserts an equal produced type string, then proves the
    Rust seam actually engages (non-None) on the alias input.
    """

    def setUp(self) -> None:
        from mypy.checker import _set_native_checker_resolver, _set_native_checker_stmts_active
        from mypy.checkexpr import _set_native_checkexpr_active, _set_native_checkexpr_resolver
        from mypy.typeops import _set_native_typeops_active, _set_native_typeops_resolver
        from mypy.wirefixup import set_wire_typeinfo_map

        self.fx = TypeFixture()
        self._base_infos = [
            self.fx.oi,
            self.fx.ai,
            self.fx.bi,
            self.fx.str_type_info,
            self.fx.type_typei,
            self.fx.std_tuplei,
            self.fx.std_listi,
        ]
        set_wire_typeinfo_map({info.fullname: info for info in self._base_infos})
        self._resolver = _type_kernel.build_native_resolver(self._base_infos, [])
        self._resolver.set_live_typeinfo_map({info.fullname: info for info in self._base_infos})
        _set_native_typeops_resolver(self._resolver)
        _set_native_checkexpr_resolver(self._resolver)
        _set_native_checker_resolver(self._resolver)
        _set_native_typeops_active(True)
        _set_native_checkexpr_active(True)
        _set_native_checker_stmts_active(True)

    def _rebuild_resolver(self, aliases: list[Any], extra_infos: list[Any] | None = None) -> None:
        from mypy.checker import _set_native_checker_resolver
        from mypy.checkexpr import _set_native_checkexpr_resolver
        from mypy.typeops import _set_native_typeops_resolver
        from mypy.wirefixup import set_wire_typeinfo_map

        infos = self._base_infos + (extra_infos or [])
        set_wire_typeinfo_map({info.fullname: info for info in infos})
        self._resolver = _type_kernel.build_native_resolver(infos, aliases)
        self._resolver.set_live_typeinfo_map({info.fullname: info for info in infos})
        _set_native_typeops_resolver(self._resolver)
        _set_native_checkexpr_resolver(self._resolver)
        _set_native_checker_resolver(self._resolver)

    def tearDown(self) -> None:
        from mypy.checker import _set_native_checker_resolver, _set_native_checker_stmts_active
        from mypy.checkexpr import _set_native_checkexpr_active, _set_native_checkexpr_resolver
        from mypy.typeops import _set_native_typeops_active, _set_native_typeops_resolver
        from mypy.wirefixup import set_wire_typeinfo_map

        _set_native_typeops_active(False)
        _set_native_typeops_resolver(None)
        _set_native_checkexpr_active(False)
        _set_native_checkexpr_resolver(None)
        _set_native_checker_stmts_active(False)
        _set_native_checker_resolver(None)
        set_wire_typeinfo_map(None)

    def _make_alias(
        self, fullname: str, target: Type, *, alias_tvars: list[TypeVarLikeType] | None = None
    ) -> TypeAlias:
        from mypy.nodes import TypeAlias

        return TypeAlias(target, fullname, "mod", -1, -1, alias_tvars=alias_tvars or [])

    def _alias_type(self, alias: TypeAlias) -> TypeAliasType:
        return TypeAliasType(alias, [])

    def _with_typeops_gate(self, active: bool, fn: Callable[[], object]) -> object:
        from mypy.typeops import _set_native_typeops_active

        _set_native_typeops_active(active)
        try:
            return fn()
        finally:
            _set_native_typeops_active(True)

    def _with_checkexpr_gate(self, active: bool, fn: Callable[[], object]) -> object:
        from mypy.checkexpr import _set_native_checkexpr_active

        _set_native_checkexpr_active(active)
        try:
            return fn()
        finally:
            _set_native_checkexpr_active(True)

    def _with_checker_gate(self, active: bool, fn: Callable[[], T]) -> T:
        from mypy.checker import _set_native_checker_stmts_active

        _set_native_checker_stmts_active(active)
        try:
            return fn()
        finally:
            _set_native_checker_stmts_active(True)

    def test_union_simplify_alias_of_a(self) -> None:
        # A = A, then Union[A-alias, A]: the alias item expands to A, which
        # dedups against the second A, collapsing the union to A.
        from mypy.typeops import _serialize_type_list

        alias = self._make_alias("mod.TA", self.fx.a)
        self._rebuild_resolver([alias])
        u = cast(UnionType, UnionType.make_union([self._alias_type(alias), self.fx.a]))
        off = self._with_typeops_gate(False, lambda: make_simplified_union(u.items, 0, -1))
        on = self._with_typeops_gate(True, lambda: make_simplified_union(u.items, 0, -1))
        assert_equal(str(on), str(off), "make_simplified_union alias parity")
        assert_equal(str(on), str(self.fx.a), "alias of A must collapse the union")
        # The Rust seam must decide on the alias input, not defer.
        rusted = _type_kernel.rust_make_simplified_union(
            _serialize_type_list([self._alias_type(alias), self.fx.a]),
            0,
            -1,
            False,
            True,
            False,
            True,
            self._resolver,
        )
        assert rusted is not None, "Rust deferred on alias union simplification"

    def test_union_simplify_alias_dedups_subtype(self) -> None:
        # Sub = A (proper subclass via MRO), then B = Sub: the alias item
        # expands to `Sub`, which is a proper subtype of A, so
        # Union[B-alias, A] must collapse to A exactly like Python.
        from mypy.typeops import _serialize_type_list

        sub = self.fx.make_type_info(
            "mod.Sub", mro=[self.fx.ai, self.fx.oi], bases=[Instance(self.fx.ai, [])]
        )
        alias = self._make_alias("mod.TB", Instance(sub, []))
        self._rebuild_resolver([alias], extra_infos=[sub])
        u = cast(UnionType, UnionType.make_union([self._alias_type(alias), self.fx.a]))
        off = self._with_typeops_gate(False, lambda: make_simplified_union(u.items, 0, -1))
        on = self._with_typeops_gate(True, lambda: make_simplified_union(u.items, 0, -1))
        assert_equal(str(on), str(off), "make_simplified_union subtype parity")
        assert_equal(str(on), "A", "alias to Sub must collapse against A")
        rusted = _type_kernel.rust_make_simplified_union(
            _serialize_type_list([self._alias_type(alias), self.fx.a]),
            0,
            -1,
            False,
            True,
            False,
            True,
            self._resolver,
        )
        assert rusted is not None, "Rust deferred on alias subtype"

    def test_union_simplify_nested_alias_flatten(self) -> None:
        # B = A, A = list[A]: the chain must resolve to list[A], which
        # stays as the union's single item (no duplicate to collapse).
        from mypy.typeops import _serialize_type_list

        alias_a = self._make_alias("mod.TA", self.fx.a)
        alias_b = self._make_alias("mod.TB", Instance(self.fx.std_listi, [self.fx.a]))
        self._rebuild_resolver([alias_a, alias_b])
        u = cast(UnionType, UnionType.make_union([self._alias_type(alias_b), self.fx.a]))
        off = self._with_typeops_gate(False, lambda: make_simplified_union(u.items, 0, -1))
        on = self._with_typeops_gate(True, lambda: make_simplified_union(u.items, 0, -1))
        assert_equal(str(on), str(off), "nested-alias make_simplified_union parity")
        rusted = _type_kernel.rust_make_simplified_union(
            _serialize_type_list([self._alias_type(alias_b), self.fx.a]),
            0,
            -1,
            False,
            True,
            False,
            True,
            self._resolver,
        )
        assert rusted is not None, "Rust deferred on nested alias flatten"

    def test_remove_redundant_alias_of_a_dedups(self) -> None:
        # Union[A-alias, A] through the redundant-union pass: both items
        # expand to A, so the second is a duplicate.
        from mypy.typeops import _remove_redundant_union_items, _serialize_type_list

        alias = self._make_alias("mod.TA", self.fx.a)
        self._rebuild_resolver([alias])
        items = [self._alias_type(alias), self.fx.a]
        off = self._with_typeops_gate(False, lambda: _remove_redundant_union_items(items, False))
        on = self._with_typeops_gate(True, lambda: _remove_redundant_union_items(items, False))
        assert_equal(str(on), str(off), "remove_redundant alias parity")
        assert on == [self.fx.a], f"alias of A must dedup, got {on!r}"
        rusted = _type_kernel.rust_remove_redundant_union_items(
            _serialize_type_list(items), _rru_flags_blob(items), False, True, self._resolver
        )
        assert rusted is not None, "Rust deferred on remove_redundant alias"

    def test_remove_redundant_alias_subtype(self) -> None:
        # B = list[A]: alias + object; the alias's proper form is a proper
        # subtype of object, so it must be removed.
        from mypy.typeops import _remove_redundant_union_items, _serialize_type_list

        alias = self._make_alias("mod.TB", Instance(self.fx.std_listi, [self.fx.a]))
        self._rebuild_resolver([alias])
        items = [self._alias_type(alias), self.fx.o]
        off = self._with_typeops_gate(False, lambda: _remove_redundant_union_items(items, False))
        on = self._with_typeops_gate(True, lambda: _remove_redundant_union_items(items, False))
        assert_equal(str(on), str(off), "remove_redundant alias subtype parity")
        assert on == [self.fx.o], f"alias to list[A] must be removed, got {on!r}"
        rusted = _type_kernel.rust_remove_redundant_union_items(
            _serialize_type_list(items), _rru_flags_blob(items), False, True, self._resolver
        )
        assert rusted is not None, "Rust deferred on remove_redundant alias subtype"

    def test_is_duplicate_mapping_alias_value(self) -> None:
        # Two **kwargs actuals where an alias to A (a non-TypedDict) is
        # among them: the check is disabled (all non-TypedDict), so the
        # result is False; the alias expands to A rather than deferring.
        from mypy.checkexpr import _serialize_type_for_checkexpr, is_duplicate_mapping

        alias = self._make_alias("mod.TA", self.fx.a)
        self._rebuild_resolver([alias])
        items = [self._alias_type(alias), self.fx.a]
        off = self._with_checkexpr_gate(
            False, lambda: is_duplicate_mapping([0, 1], items, [ARG_STAR2, ARG_STAR2])
        )
        on = self._with_checkexpr_gate(
            True, lambda: is_duplicate_mapping([0, 1], items, [ARG_STAR2, ARG_STAR2])
        )
        assert_equal(str(on), str(off), "is_duplicate_mapping alias parity")
        assert on is False, "two non-TypedDict **kwargs must not duplicate"
        rusted = _type_kernel.rust_is_duplicate_mapping(
            [0, 1],
            [
                _serialize_type_for_checkexpr(self._alias_type(alias)),
                _serialize_type_for_checkexpr(self.fx.a),
            ],
            [int(ARG_STAR2.value), int(ARG_STAR2.value)],
            self._resolver,
        )
        assert rusted is not None, "Rust deferred on is_duplicate_mapping alias"

    def test_type_requires_usage_alias_to_coroutine(self) -> None:
        # A = Coroutine: the alias expands to typing.Coroutine and the note
        # code fires; the plain instance (no __await__) stays a no-op.
        from mypy.checker import _serialize_type_for_checker, _try_native_type_requires_usage

        # Hand-build a typing.Coroutine TypeInfo: three typevars (YieldT,
        # SendT, ReturnT) so it is a coroutine-shaped instance.
        coro = self.fx.make_type_info("typing.Coroutine", typevars=["T_co", "T_contra", "T_ret"])
        alias = self._make_alias(
            "mod.TCoroutine", Instance(coro, [self.fx.anyt, self.fx.o, self.fx.o])
        )
        self._rebuild_resolver([alias])
        # End-to-end shim: the note code fires only when the checker gate and
        # resolver are installed, and the alias is expanded to Coroutine.
        off = self._with_checker_gate(
            False, lambda: _try_native_type_requires_usage(self._alias_type(alias))
        )
        on = self._with_checker_gate(
            True, lambda: _try_native_type_requires_usage(self._alias_type(alias))
        )
        assert off is None, f"gate-off shim must defer, got {off!r}"
        assert on is not None and on[0] == "Are you missing an await?", f"got {on!r}"
        # Direct seam call proves the Rust expansion actually fired.
        rusted = _type_kernel.rust_type_requires_usage(
            _serialize_type_for_checker(self._alias_type(alias)), self._resolver
        )
        assert rusted is not None, "Rust deferred on alias to Coroutine"


@skipUnless(_NATIVE_WIRE_ENABLED, "requires TEST_NATIVE_TYPE_KERNEL=1 and type_kernel ext")
class NativeCustomSpecialMethodSuite(Suite):
    """Parity for the Rust `custom_special_method` port (mypy.typeops).

    The Rust seam mirrors `mypy.typeops.custom_special_method`
    (typeops.py:1936-1974): the Instance branch walks the MRO via the
    snapshot `mro` (like `TypeInfo.get`), and the Overloaded / TypeType
    branches decide from the wire shapes with no deferral for the
    non-type-obj / non-Instance / no-metaclass tails. Toggling the
    typeops gate off (pure Python on live types) and on (Rust seam on
    serialized types) must produce identical results, for the
    `custom_special_method` entry and for `has_custom_eq_checks`.
    """

    def setUp(self) -> None:
        from mypy.typeops import _set_native_typeops_active, _set_native_typeops_resolver
        from mypy.wirefixup import set_wire_typeinfo_map

        self.fx = TypeFixture()
        # Per-test type infos, filled in by _info() / _dunder() so each
        # test controls the member_definers and MRO.
        self._typeinfos: list[TypeInfo] = []
        type_infos = []
        for name in dir(self.fx):
            if not name.endswith("i"):
                continue
            value = getattr(self.fx, name)
            if _is_type_info(value):
                type_infos.append(value)
        set_wire_typeinfo_map({info.fullname: info for info in type_infos})
        self._resolver = _type_kernel.build_native_resolver(type_infos, [])
        _set_native_typeops_active(True)
        _set_native_typeops_resolver(self._resolver)

    def tearDown(self) -> None:
        from mypy.typeops import _set_native_typeops_active, _set_native_typeops_resolver
        from mypy.wirefixup import set_wire_typeinfo_map

        _set_native_typeops_active(False)
        _set_native_typeops_resolver(None)
        set_wire_typeinfo_map(None)

    def _info(self, fullname: str, bases: list[TypeInfo] | None = None) -> TypeInfo:
        info = self.fx.make_type_info(fullname)
        if bases:
            info.bases = [Instance(b, []) for b in bases]
            info.mro = [info] + [b for b in bases] + [self.fx.oi]
        else:
            info.mro = [info, self.fx.oi]
        # Inject the modified info into the resolver so the Rust seam
        # sees the same member_definers / mro the Python path sees.
        self._typeinfos.append(info)
        self._rebuild_resolver()
        return info

    def _meta_info(self, fullname: str, cls: TypeInfo | None = None) -> TypeInfo:
        """A metaclass TypeInfo; when `cls` is given, set cls.metaclass_type."""
        info = self.fx.make_type_info(fullname)
        info.mro = [info] + _base_infos(self.fx)
        if cls is not None:
            cls.metaclass_type = Instance(info, [])
        self._typeinfos.append(info)
        self._rebuild_resolver()
        return info

    def _rebuild_resolver(self) -> None:
        self._resolver = _type_kernel.build_native_resolver(
            self._typeinfos + _base_infos(self.fx), []
        )

    def _object_infos(self) -> list[TypeInfo]:
        return [self.fx.oi]

    def _dunder(self, info: TypeInfo, name: str, definer: TypeInfo) -> None:
        node = FuncDef(name, [], None, None)
        node.info = definer
        info.names[name] = SymbolTableNode(MDEF, node)
        # The resolver snapshots `names` at build time, so adding a
        # member requires a rebuild for the Rust seam to see it.
        self._rebuild_resolver()

    def _with_gate(self, active: bool, fn: Callable[[], T]) -> T:
        from mypy.typeops import _set_native_typeops_active

        _set_native_typeops_active(active)
        try:
            return fn()
        finally:
            _set_native_typeops_active(True)

    def _assert_par(self, typ: Type, name: str = "__eq__", check_all: bool = False) -> None:
        from mypy.typeops import custom_special_method

        off = self._with_gate(False, lambda: custom_special_method(typ, name, check_all))
        on = self._with_gate(True, lambda: custom_special_method(typ, name, check_all))
        assert on == off, f"custom_special_method parity {typ!r}/{name}: off={off} on={on}"

    def _assert_engages(self, typ: Type, name: str = "__eq__") -> None:
        from mypy.typeops import _serialize_type

        result = _type_kernel.rust_custom_special_method(
            _serialize_type(typ), name, False, self._resolver
        )
        assert result is not None, f"Rust custom_special_method did not engage for {typ!r}/{name}"

    def _assert_defers(self, typ: Type, name: str = "__eq__") -> None:
        from mypy.typeops import _serialize_type

        result = _type_kernel.rust_custom_special_method(
            _serialize_type(typ), name, False, self._resolver
        )
        assert result is None, f"Rust custom_special_method expected defer for {typ!r}/{name}"

    def test_custom_dunder_direct(self) -> None:
        # Genuinely custom dunder on the class itself.
        info = self._info("mod.Custom")
        self._dunder(info, "__eq__", info)
        t = Instance(info, [])
        self._assert_par(t)
        self._assert_par(t, "__ne__")
        self._assert_engages(t)

    def test_inherited_from_object_false(self) -> None:
        # No custom dunder: MRO finds it on builtins.object -> False.
        # This was the deferral bulk before the MRO walk.
        info = self._info("mod.Plain")
        t = Instance(info, [])
        self._assert_par(t)
        self._assert_engages(t)

    def test_custom_inherited_from_base(self) -> None:
        # Custom dunder inherited from a base class: MRO walk must find
        # it on the base (definer = base), not defer.
        base = self._info("mod.Base")
        self._dunder(base, "__eq__", base)
        child = self._info("mod.Child", [base])
        t = Instance(child, [])
        self._assert_par(t)
        self._assert_engages(t)

    def test_different_special_methods(self) -> None:
        # __bool__ on the class, but querying __format__ (missing on the
        # live class and object): Python's `typ.type.get` misses the
        # MRO walk as well and falls to the `return False` tail.
        info = self._info("mod.Booler")
        self._dunder(info, "__bool__", info)
        t = Instance(info, [])
        self._assert_par(t, "__bool__")
        self._assert_par(t, "__format__")
        self._assert_engages(t, "__format__")

    def test_missing_member_not_custom_no_defer(self) -> None:
        # Class with NO dunder at all (not even inherited): Python tail
        # returns False; Rust must too (was `None` before).
        info = self._info("mod.None")
        t = Instance(info, [])
        self._assert_par(t)
        self._assert_engages(t)

    def test_any_type_true(self) -> None:
        # AnyType: Python returns True unconditionally (uncertain).
        t = AnyType(TypeOfAny.special_form)
        self._assert_par(t)
        self._assert_engages(t)

    def test_union_any_short_circuit(self) -> None:
        # Union with an Any member: `any(...)` short-circuits on the
        # Any -> True before examining the Instance.
        info = self._info("mod.U")
        t = UnionType([Instance(info, []), AnyType(TypeOfAny.special_form)])
        self._assert_par(t)
        self._assert_engages(t)

    def test_non_type_obj_overloaded_false(self) -> None:
        # Overloaded whose first item is a plain function (not a type
        # obj): FunctionLike.is_type_obj() False -> tail False.
        item = CallableType([self.fx.a], [ARG_POS], ["x"], self.fx.a, self.fx.function, name="f")
        t = Overloaded([item])
        self._assert_par(t)
        self._assert_engages(t)

    def test_type_obj_overloaded_via_metaclass(self) -> None:
        # Overloaded whose first item IS a type obj: recurse on the
        # fallback (metaclass) Instance. The fallback class must be a
        # metaclass (MRO includes builtins.type) for is_type_obj.
        mc = self._meta_info("builtins.type")
        item = CallableType([], [], [], self.fx.a, Instance(mc, []), name="__call__")
        t = Overloaded([item])
        self._assert_par(t)
        self._assert_engages(t)

    def test_typetype_metaclass_lookup(self) -> None:
        info = self._info("mod.Klass")
        mc = self._meta_info("builtins.type", cls=info)
        self._dunder(mc, "__eq__", mc)
        self._rebuild_resolver()
        t = TypeType.make_normalized(Instance(info, []))
        self._assert_par(t)
        self._assert_engages(t)

    def test_typetype_no_metaclass_false(self) -> None:
        # TypeType of a class with no metaclass: Python skips the
        # metaclass branch and falls to False.
        info = self._info("mod.NoMeta")
        t = TypeType.make_normalized(Instance(info, []))
        self._assert_par(t)
        self._assert_engages(t)

    def test_typetype_non_instance_item_false(self) -> None:
        # TypeType(Any): item not an Instance -> False.
        t = TypeType(AnyType(TypeOfAny.special_form))
        self._assert_par(t)
        self._assert_engages(t)

    def test_type_alias_structural_defer(self) -> None:
        # TypeAliasType: no alias target on the wire -> structural defer
        # to Python (which expands via get_proper_type).
        from mypy.nodes import TypeAlias

        t = TypeAliasType(TypeAlias(cast(Any, None), "mod.Alias", "mod", -1, -1), [])
        self._assert_defers(t)

    def _rebuild_resolver_with_aliases(self, aliases: list[Any]) -> None:
        from mypy.typeops import _set_native_typeops_resolver
        from mypy.wirefixup import set_wire_typeinfo_map

        infos = self._typeinfos + _base_infos(self.fx)
        set_wire_typeinfo_map({info.fullname: info for info in infos})
        self._resolver = _type_kernel.build_native_resolver(infos, aliases)
        _set_native_typeops_resolver(self._resolver)

    def test_type_alias_expands_to_custom(self) -> None:
        # A top-level TypeAliasType expands through the alias resolver,
        # mirroring `typ = get_proper_type(typ)` (typeops.py:1981): the
        # alias target carries a custom __eq__, so the seam says True.
        from mypy.nodes import TypeAlias

        info = self._info("mod.Custom")
        self._dunder(info, "__eq__", info)
        alias = TypeAlias(Instance(info, []), "mod.Alias", "mod", -1, -1)
        self._rebuild_resolver_with_aliases([alias])
        t = TypeAliasType(alias, [])
        self._assert_par(t)
        self._assert_par(t, "__ne__")
        self._assert_engages(t)

    def test_has_custom_eq_checks_par(self) -> None:
        from mypy.checker import (
            _set_native_checker_active,
            _set_native_checker_resolver,
            has_custom_eq_checks,
        )

        cases = [
            self._info("mod.Eq"),  # no dunders at all
            self._info("mod.Both"),  # custom __eq__ + __ne__
            self._info("mod.NeOnly"),  # custom __ne__ only
            self._info("mod.PlainAgain"),
        ]
        for info in cases:
            if info.fullname == "mod.Eq":
                pass
            elif info.fullname == "mod.Both":
                self._dunder(info, "__eq__", info)
                self._dunder(info, "__ne__", info)
            elif info.fullname == "mod.NeOnly":
                self._dunder(info, "__ne__", info)
        self._resolver = _type_kernel.build_native_resolver(
            self._typeinfos + _base_infos(self.fx), []
        )
        _set_native_checker_active(True)
        _set_native_checker_resolver(self._resolver)
        try:
            for info in cases:
                t = Instance(info, [])
                off = self._with_gate(False, lambda: has_custom_eq_checks(t))
                on = self._with_gate(True, lambda: has_custom_eq_checks(t))
                assert on == off, f"has_custom_eq_checks parity {info.fullname}: {off} vs {on}"
        finally:
            _set_native_checker_active(False)
            _set_native_checker_resolver(None)


@skipUnless(_NATIVE_WIRE_ENABLED, "requires TEST_NATIVE_TYPE_KERNEL=1 and type_kernel ext")
class NativeCheckArgumentTypesPlanSuite(Suite):
    """Parity for the Rust `check_argument_types` plan port (mypy.checkexpr).

    `ExpressionChecker.check_argument_types` expands each formal's actual
    arguments against the callee signature: per formal it derives the
    effective `callee_arg_types`/`callee_arg_kinds` and
    `actual_types`/`actual_kinds` (or a too-many/too-few decision), then
    runs the `ArgTypeExpander` + `check_arg` loop. The Rust port derives
    those per-formal plans; the shim reports count errors and drives the
    stateful loop. Toggling the checkexpr gate off (pure Python) and on
    (Rust seam) must record identical message and `check_arg` calls, and a
    direct seam call proves the Rust planner engages rather than silently
    deferring.
    """

    def setUp(self) -> None:
        from mypy.checkexpr import _set_native_checkexpr_active, _set_native_checkexpr_resolver
        from mypy.wirefixup import set_wire_typeinfo_map

        self.fx = TypeFixture()
        type_infos = []
        for name in dir(self.fx):
            if not name.endswith("i"):
                continue
            value = getattr(self.fx, name)
            if _is_type_info(value):
                type_infos.append(value)
        set_wire_typeinfo_map({info.fullname: info for info in type_infos})
        # Clear placeholder primitives so wire fixup maps type_refs to the
        # fixture instances (mirrors the bind_self suite).
        from mypy.types import instance_cache

        instance_cache.int_type = None
        instance_cache.str_type = None
        instance_cache.bool_type = None
        instance_cache.object_type = None
        instance_cache.function_type = None
        self._set_active = _set_native_checkexpr_active
        self._set_active(True)
        self._resolver = _type_kernel.build_native_resolver(type_infos, [])
        _set_native_checkexpr_resolver(self._resolver)

    def tearDown(self) -> None:
        from mypy.checkexpr import _set_native_checkexpr_resolver
        from mypy.wirefixup import set_wire_typeinfo_map

        self._set_active(False)
        _set_native_checkexpr_resolver(None)
        set_wire_typeinfo_map(None)

    def _stub_checker(self) -> tuple[Any, list[str]]:
        """Minimal `ExpressionChecker` that records its effects.

        `check_argument_types` needs `self.chk.named_type` (var-arg
        validity and the `ArgumentInferContext`), `self.chk.msg` (error
        recording), and `self.check_arg`. The msg recorder and the passed
        `check_arg` both append to the shared log so gate-off and gate-on
        runs can be compared.
        """
        from mypy.checker import TypeChecker
        from mypy.checkexpr import ExpressionChecker
        from mypy.infer import ArgumentInferContext

        fx = self.fx
        log: list[str] = []

        def named_type(name: str) -> Instance:
            if "[" in name:
                raise AssertionError(f"named_type got parameterized {name}")
            return Instance(fx.make_type_info(name), [])

        def named_generic_type(name: str, args: list[Type]) -> Instance:
            return Instance(fx.make_type_info(name), args)

        class _Msg:
            def too_many_arguments(self, callee: CallableType, context: Context) -> None:
                del callee, context
                log.append("too_many")

            def too_few_arguments(
                self,
                callee: CallableType,
                context: Context,
                argument_names: Sequence[str | None] | None,
            ) -> None:
                del callee, context, argument_names
                log.append("too_few")

            def invalid_var_arg(self, typ: Type, context: Context) -> None:
                del typ, context
                log.append("invalid_var_arg")

            def invalid_keyword_var_arg(
                self, typ: Type, is_mapping: bool, context: Context
            ) -> None:
                del typ, context
                log.append(f"invalid_keyword_var_arg(mapping={is_mapping})")

        chk = TypeChecker.__new__(TypeChecker)
        chk.named_type = named_type  # type: ignore[method-assign]
        chk.named_generic_type = named_generic_type  # type: ignore[method-assign]
        chk.msg = _Msg()  # type: ignore[assignment]

        checker = ExpressionChecker.__new__(ExpressionChecker)
        checker.chk = chk
        checker._arg_infer_context_cache = ArgumentInferContext(
            named_type("typing.Mapping"), named_type("typing.Iterable")
        )
        return checker, log

    def _exprs(self, n: int) -> list[Expression]:
        from mypy.nodes import TempNode
        from mypy.types import AnyType, TypeOfAny

        return [TempNode(AnyType(TypeOfAny.special_form)) for _ in range(n)]

    def _ctx(self) -> Context:
        ctx = Context(5, 5)
        ctx.end_line = 6
        ctx.end_column = 7
        return ctx

    def _callee(self, arg_types: list[Type], arg_kinds: list[ArgKind]) -> CallableType:
        return CallableType(
            arg_types, arg_kinds, [None] * len(arg_types), self.fx.nonet, self.fx.function
        )

    def _run(
        self,
        arg_types: list[Type],
        arg_kinds: list[ArgKind],
        callee: CallableType,
        f2a: list[list[int]],
        *,
        assert_engages: bool = True,
    ) -> None:
        from mypy.checkexpr import ExpressionChecker

        def run_once() -> tuple[list[str], list[str]]:
            checker, log = self._stub_checker()
            check_calls: list[str] = []

            def check_arg(
                caller_type: Type,
                original_caller_type: Type,
                caller_kind: ArgKind,
                callee_type: Type,
                n: int,
                m: int,
                callee: CallableType,
                object_type: Type | None,
                context: Context,
                outer_context: Context,
            ) -> None:
                del callee, object_type, context, outer_context
                check_calls.append(
                    f"check_arg({caller_type}, {original_caller_type}, "
                    f"{caller_kind}, {callee_type}, actual{n}, formal{m})"
                )

            ExpressionChecker.check_argument_types(
                checker,
                arg_types,
                arg_kinds,
                self._exprs(len(arg_types)),
                callee,
                f2a,
                self._ctx(),
                check_arg=check_arg,
            )
            return log, check_calls

        self._set_active(False)
        off_msgs, off_calls = run_once()
        self._set_active(True)
        on_msgs, on_calls = run_once()
        assert_equal(on_msgs, off_msgs, f"message parity {callee}")
        assert_equal(on_calls, off_calls, f"check_arg parity {callee}")
        if assert_engages:
            self._assert_engages(arg_types, arg_kinds, callee, f2a)

    def _assert_engages(
        self,
        arg_types: list[Type],
        arg_kinds: list[ArgKind],
        callee: CallableType,
        f2a: list[list[int]],
    ) -> None:
        from mypy.checkexpr import (  # type: ignore[attr-defined]
            _rust_check_argument_types_plan,
            _serialize_type_for_checkexpr,
        )

        assert _rust_check_argument_types_plan is not None
        result = _rust_check_argument_types_plan(
            self._resolver,
            [_serialize_type_for_checkexpr(t) for t in arg_types],
            [int(k.value) for k in arg_kinds],
            f2a,
            _serialize_type_for_checkexpr(callee),
        )
        assert result is not None, "Rust check_argument_types did not engage"

    def test_simple_args(self) -> None:
        # def f(a: A, b: B); f(x, y) -> one check_arg per formal.
        # No unpack formals, so the seam skips wire serialization.
        fx = self.fx
        callee = self._callee([fx.a, fx.b], [ARG_POS, ARG_POS])
        self._run([fx.a, fx.b], [ARG_POS, ARG_POS], callee, [[0], [1]], assert_engages=False)

    def test_vararg_match(self) -> None:
        # def f(*args: A); f(A, B, A) -> all three actuals to formal 0.
        # ARG_STAR formal is not UnpackType, so the seam skips.
        fx = self.fx
        callee = self._callee([fx.a], [ARG_STAR])
        self._run(
            [fx.a, fx.b, fx.a],
            [ARG_POS, ARG_POS, ARG_POS],
            callee,
            [[0, 1, 2]],
            assert_engages=False,
        )

    def test_too_many_arguments(self) -> None:
        # def f(x: tuple[A, B]); caller passes 3 positional actuals.
        fx = self.fx
        callee = self._callee(
            [UnpackType(TupleType([fx.a, fx.b], self.fx.std_tuple, False))], [ARG_POS]
        )
        self._run([fx.a, fx.b, fx.c], [ARG_POS, ARG_POS, ARG_POS], callee, [[0, 1, 2]])

    def test_too_few_arguments(self) -> None:
        # def f(x: tuple[A, B]); caller passes 1 positional actual.
        fx = self.fx
        callee = self._callee(
            [UnpackType(TupleType([fx.a, fx.b], self.fx.std_tuple, False))], [ARG_POS]
        )
        self._run([fx.a], [ARG_POS], callee, [[0]])

    def test_unpacked_tuple_reunify(self) -> None:
        # def f(x: Tuple[Unpack[Ts], A]); caller passes a one-item unpacked
        # tuple whose Unpack target is the same shape, plus a suffix B, so
        # formal_to_actual is [[0, 1]]. The first actual is the one-item

        # unpacked tuple reunified with the suffix; Rust expands callee to
        # [Unpack[Ts], A] with kinds [ARG_STAR, ARG_POS].
        fx = self.fx
        inner_unpack = UnpackType(fx.ts)
        inner_tuple = TupleType([inner_unpack, fx.a], self.fx.std_tuple, False)
        callee = self._callee([UnpackType(inner_tuple)], [ARG_POS])
        caller_tuple = TupleType([UnpackType(inner_tuple), fx.b], self.fx.std_tuple, False)
        self._run([caller_tuple, fx.b], [ARG_STAR, ARG_POS], callee, [[0, 1]])

    def test_plain_tuple_unpack_target(self) -> None:
        # def f(x: tuple[A, ...]); call with two actuals.
        fx = self.fx
        callee = self._callee([UnpackType(Instance(fx.std_tuplei, [fx.a]))], [ARG_POS])
        self._run([fx.a, fx.b], [ARG_POS, ARG_POS], callee, [[0, 1]])

    def test_type_alias_defers_whole_call(self) -> None:
        # A TypeAliasType in a callee formal cannot be reproduced by Rust
        # (no alias target on the wire), so `plan_for_formal` returns None
        # for the whole call and Python runs the pure body. Both paths

        # produce the same check_arg for the non-alias formal.
        from mypy.nodes import TypeAlias as TypeAliasNode
        from mypy.types import TypeAliasType as TypeAliasTypeCls

        fx = self.fx
        alias_node = TypeAliasNode(fx.a, "mod.AL", "mod", -1, -1)
        alias = TypeAliasTypeCls(alias_node, [])
        callee = self._callee([alias, fx.b], [ARG_POS, ARG_POS])
        self._run([fx.a, fx.b], [ARG_POS, ARG_POS], callee, [[0], [1]], assert_engages=False)
        # The seam must actively refuse the alias (prove the seal, not a
        # silent pass-through).
        from mypy.checkexpr import (  # type: ignore[attr-defined]
            _rust_check_argument_types_plan,
            _serialize_type_for_checkexpr,
        )

        result = _rust_check_argument_types_plan(
            self._resolver,
            [_serialize_type_for_checkexpr(t) for t in [fx.a, fx.b]],
            [int(k.value) for k in [ARG_POS, ARG_POS]],
            [[0], [1]],
            _serialize_type_for_checkexpr(callee),
        )
        assert result is None, "expected Rust to defer on a TypeAliasType formal"


@skipUnless(_NATIVE_WIRE_ENABLED, "requires TEST_NATIVE_TYPE_KERNEL=1 and type_kernel ext")
class NativeEqualityValueInfoSuite(Suite):
    """Parity for the Rust `equality_value_info` port (mypy.checker).

    `equality_value_info` collects the value-equality domains a type
    participates in; `is_equality_ambiguous_for_narrowing` uses it to
    detect cross-domain equality (IntEnum vs int, StrEnum vs str). The
    Rust port folds `combine_equality_value_info` into the recursion and
    reads the resolver-required metadata (mro, is_enum) from the TypeInfo
    snapshot. Toggling the checker gate off (pure Python) and on (Rust)
    must produce identical results, and a direct seam call proves the Rust
    function engages rather than silently deferring.
    """

    def setUp(self) -> None:
        from mypy.checker import _set_native_checker_active, _set_native_checker_resolver

        self.fx = TypeFixture()
        self.int_info = self.fx.make_type_info("builtins.int")
        # An IntEnum: is_enum set, mro through builtins.int -> numeric domain.
        self.enum_info = self.fx.make_type_info("mod.Color", mro=[self.int_info, self.fx.oi])
        self.enum_info.is_enum = True
        type_infos = []
        for name in dir(self.fx):
            if not name.endswith("i"):
                continue
            value = getattr(self.fx, name)
            if _is_type_info(value):
                type_infos.append(value)
        # Make sure the str/object TypeInfos are snapshotted: the `dir(fx)`
        # scan above only picks `*i` attrs and `str_type_info` /
        # `bool_type_info` do not end in "i".
        type_infos.extend([self.fx.str_type_info, self.fx.bool_type_info])
        type_infos.extend([self.int_info, self.enum_info])
        self.resolver = _type_kernel.build_native_resolver(type_infos, [])
        _set_native_checker_active(True)
        _set_native_checker_resolver(self.resolver)

    def tearDown(self) -> None:
        from mypy.checker import _set_native_checker_active, _set_native_checker_resolver

        _set_native_checker_active(False)
        _set_native_checker_resolver(None)

    def _with_gate(self, active: bool, fn: Callable[[], T]) -> T:
        from mypy.checker import _set_native_checker_active

        _set_native_checker_active(active)
        try:
            return fn()
        finally:
            _set_native_checker_active(True)

    def _normalize(
        self, info: object
    ) -> tuple[bool, frozenset[tuple[str, frozenset[str], frozenset[str]]]]:
        from mypy.checker import EqualityValueInfo

        assert isinstance(info, EqualityValueInfo)
        return (
            info.is_top,
            frozenset(
                (domain, frozenset(domain_info.type_names), frozenset(domain_info.enum_type_names))
                for domain, domain_info in info.domains.items()
            ),
        )

    def _assert_par(self, typ: Type) -> None:
        from mypy.checker import equality_value_info

        off = self._normalize(self._with_gate(False, lambda: equality_value_info(typ)))
        on = self._normalize(self._with_gate(True, lambda: equality_value_info(typ)))
        assert_equal(on, off, f"equality_value_info parity {typ}")

    def _assert_engages(self, typ: Type) -> None:
        from mypy.checker import _serialize_type_for_checker

        result = _type_kernel.rust_equality_value_info(
            _serialize_type_for_checker(typ), self.resolver
        )
        assert result is not None, f"Rust equality_value_info did not engage for {typ}"

    def test_str_instance(self) -> None:
        # Instance of builtins.str -> open str domain, no enum type names.
        from mypy.checker import equality_value_info

        s = Instance(self.fx.str_type_info, [])
        self._assert_par(s)
        result = self._normalize(equality_value_info(s))
        assert_equal(
            result,
            (False, frozenset({("builtins.str", frozenset({"builtins.str"}), frozenset())})),
        )
        self._assert_engages(s)

    def test_int_enum_literal(self) -> None:
        # An IntEnum literal's fallback is the enum Instance; the enum's mro
        # hits builtins.int -> numeric domain with the enum name in both sets.
        from mypy.checker import equality_value_info

        enum_inst = Instance(self.enum_info, [])
        lit = LiteralType(1, enum_inst)
        self._assert_par(lit)
        result = self._normalize(equality_value_info(lit))
        assert_equal(
            result,
            (
                False,
                frozenset(
                    {("builtins.numeric", frozenset({"mod.Color"}), frozenset({"mod.Color"}))}
                ),
            ),
        )
        self._assert_engages(lit)

    def test_union(self) -> None:
        # combine over the member infos: str + plain non-enum A.
        u = UnionType([Instance(self.fx.str_type_info, []), self.fx.a])
        self._assert_par(u)
        self._assert_engages(u)

    def test_typevar_with_values(self) -> None:
        # TypeVar.values non-empty: combine over the values.
        tv = TypeVarType(
            "T",
            "T",
            TypeVarId(1),
            [Instance(self.fx.str_type_info, [])],
            self.fx.o,
            AnyType(TypeOfAny.from_omitted_generics),
        )
        self._assert_par(tv)
        self._assert_engages(tv)

    def test_typevar_upper_bound(self) -> None:
        # TypeVar.values empty: recurse on the upper_bound (object -> top).
        tv = TypeVarType(
            "T", "T", TypeVarId(1), [], self.fx.o, AnyType(TypeOfAny.from_omitted_generics)
        )
        self._assert_par(tv)
        self._assert_engages(tv)

    def test_any(self) -> None:
        self._assert_par(self.fx.anyt)
        self._assert_engages(self.fx.anyt)

    def test_object_instance(self) -> None:
        # builtins.object is a top-like value info.
        self._assert_par(self.fx.o)
        self._assert_engages(self.fx.o)

    def test_plain_instance(self) -> None:
        # A has no value-equality domain members in its mro: no domains.
        self._assert_par(self.fx.a)
        self._assert_engages(self.fx.a)


@skipUnless(_NATIVE_WIRE_ENABLED, "requires TEST_NATIVE_TYPE_KERNEL=1 and type_kernel ext")
class NativeSupportedSelfTypeSuite(Suite):
    """Parity for the Rust `supported_self_type` port (mypy.typeops).

    `supported_self_type` decides whether a self annotation is a supported
    kind: an `X` or `Type[X]` where `X` is an instance other than its fully
    generic form, or a type variable; a callable is allowed only when
    `allow_callable`. The Rust port mirrors the Python body: `TypeType`
    recurses with the default flags, a callable answers true only when
    allowed, and the Instance branch compares its args against the class's
    declared type parameters (read live so the namespaced `TypeVarId`
    identity is exact). Toggling the typeops gate off (pure Python) and on
    (Rust seam) must produce identical booleans, and a direct seam call
    proves the Rust function engages rather than silently deferring.
    """

    def setUp(self) -> None:
        from mypy.typeops import _set_native_typeops_active, _set_native_typeops_resolver
        from mypy.wirefixup import set_wire_typeinfo_map

        self.fx = TypeFixture()
        type_infos = []
        for name in dir(self.fx):
            if not name.endswith("i"):
                continue
            value = getattr(self.fx, name)
            if _is_type_info(value):
                type_infos.append(value)
        self._resolver = _type_kernel.build_native_resolver(type_infos, [])
        self._live_map = {info.fullname: info for info in type_infos}
        self._resolver.set_live_typeinfo_map(dict(self._live_map))
        set_wire_typeinfo_map(self._live_map)
        _set_native_typeops_active(True)
        _set_native_typeops_resolver(self._resolver)

    def tearDown(self) -> None:
        from mypy.typeops import _set_native_typeops_active, _set_native_typeops_resolver
        from mypy.wirefixup import set_wire_typeinfo_map

        _set_native_typeops_active(False)
        _set_native_typeops_resolver(None)
        set_wire_typeinfo_map(None)

    def _call(
        self, typ: ProperType, allow_callable: bool = True, allow_instances: bool = True
    ) -> bool:
        from mypy.typeops import supported_self_type

        return supported_self_type(
            typ, allow_callable=allow_callable, allow_instances=allow_instances
        )

    def _with_gate(self, active: bool, fn: Callable[[], bool]) -> bool:
        from mypy.typeops import _set_native_typeops_active

        _set_native_typeops_active(active)
        try:
            return fn()
        finally:
            _set_native_typeops_active(True)

    def _assert_par(
        self, typ: ProperType, allow_callable: bool = True, allow_instances: bool = True
    ) -> None:
        off = self._with_gate(False, lambda: self._call(typ, allow_callable, allow_instances))
        on = self._with_gate(True, lambda: self._call(typ, allow_callable, allow_instances))
        assert_equal(on, off, f"supported_self_type parity {typ}")

    def _assert_engages(self, typ: ProperType) -> None:
        from mypy.typeops import _serialize_type

        result = _type_kernel.rust_supported_self_type(
            _serialize_type(typ), self._resolver, True, True
        )
        assert result is not None, f"Rust supported_self_type did not engage for {typ}"

    def test_nongeneric_instance(self) -> None:
        # A == fill_typevars(A): the default self, unsupported.
        self._assert_par(self.fx.a)
        assert self._with_gate(True, lambda: self._call(self.fx.a)) is False
        self._assert_engages(self.fx.a)

    def test_fully_generic_instance(self) -> None:
        # G[T] == fill_typevars(G): the default self, unsupported.
        gt = Instance(self.fx.gi, [self.fx.t])
        self._assert_par(gt)
        assert self._with_gate(True, lambda: self._call(gt)) is False
        self._assert_engages(gt)

    def test_instance_with_arg(self) -> None:
        # G[A] != G[T]: a supported concrete self.
        ga = Instance(self.fx.gi, [self.fx.a])
        self._assert_par(ga)
        assert self._with_gate(True, lambda: self._call(ga)) is True
        self._assert_engages(ga)

    def test_typevar(self) -> None:
        self._assert_par(self.fx.t)
        assert self._with_gate(True, lambda: self._call(self.fx.t)) is True
        self._assert_engages(self.fx.t)

    def test_callable(self) -> None:
        ct = CallableType(
            [self.fx.a], [ARG_POS], [None], self.fx.a, Instance(self.fx.oi, []), name="<init>"
        )
        self._assert_par(ct)
        assert self._with_gate(True, lambda: self._call(ct)) is True
        self._assert_engages(ct)

    def test_typetype(self) -> None:
        # Type[A] recurses to the non-generic A -> unsupported.
        self._assert_par(TypeType(self.fx.a))
        assert self._with_gate(True, lambda: self._call(TypeType(self.fx.a))) is False
        self._assert_engages(TypeType(self.fx.a))

    def test_typetype_generic_arg(self) -> None:
        # Type[G[A]] -> supported; Type[G[T]] -> unsupported.
        ga = Instance(self.fx.gi, [self.fx.a])
        gt = Instance(self.fx.gi, [self.fx.t])
        self._assert_par(TypeType(ga))
        self._assert_par(TypeType(gt))
        assert self._with_gate(True, lambda: self._call(TypeType(ga))) is True
        assert self._with_gate(True, lambda: self._call(TypeType(gt))) is False
        self._assert_engages(TypeType(ga))
        self._assert_engages(TypeType(gt))

    def test_flags(self) -> None:
        # allow_instances=False rejects a plain Instance...
        ga = Instance(self.fx.gi, [self.fx.a])
        self._assert_par(ga, allow_instances=False)
        assert self._with_gate(True, lambda: self._call(ga, allow_instances=False)) is False
        # ...but Type[A] still recurses with the default flags, so the
        # (unsupported) non-generic A decision survives.
        self._assert_par(TypeType(self.fx.a), allow_instances=False)
        assert (
            self._with_gate(True, lambda: self._call(TypeType(self.fx.a), allow_instances=False))
            is False
        )

    def test_callable_flag(self) -> None:
        # allow_callable=False rejects a bare callable...
        ct = CallableType(
            [self.fx.a], [ARG_POS], [None], self.fx.a, Instance(self.fx.oi, []), name="<init>"
        )
        self._assert_par(ct, allow_callable=False)
        assert self._with_gate(True, lambda: self._call(ct, allow_callable=False)) is False
        # ...but Type[callable] recurses with default flags, so it is allowed.
        self._assert_par(TypeType(ct), allow_callable=False)
        assert (
            self._with_gate(True, lambda: self._call(TypeType(ct), allow_callable=False)) is True
        )


@skipUnless(_NATIVE_WIRE_ENABLED, "requires TEST_NATIVE_TYPE_KERNEL=1 and type_kernel ext")
class NativeGetPropertyTypeSuite(Suite):
    """Parity for the Rust `get_property_type` port (mypy.checker).

    `get_property_type` maps a `CallableType` to the proper type of its
    `ret_type`, an `Overloaded` to the proper `items[0].ret_type`, and any
    other `ProperType` to itself. The Rust port reads the live object graph
    (no wire round-trip) and returns the live `ProperType`. Toggling the
    checker-stmts gate off (pure Python) and on (Rust seam) must produce
    identical `str(...)` output, and a direct seam call proves the Rust
    function engages rather than silently deferring.
    """

    def setUp(self) -> None:
        from mypy.checker import _set_native_checker_stmts_active

        self.fx = TypeFixture()
        self._set_active = _set_native_checker_stmts_active
        self._set_active(True)

    def tearDown(self) -> None:
        self._set_active(False)

    def _with_gate(self, active: bool, fn: Callable[[], T]) -> T:
        self._set_active(active)
        try:
            return fn()
        finally:
            self._set_active(True)

    def _assert_par(self, t: ProperType, expected: str) -> None:
        from mypy.checker import get_property_type

        off = self._with_gate(False, lambda: get_property_type(t))
        on = self._with_gate(True, lambda: get_property_type(t))
        assert_equal(str(on), str(off), f"get_property_type parity {t}")
        result = self._with_gate(True, lambda: get_property_type(t))
        assert_equal(str(result), expected)
        assert isinstance(result, ProperType)

    def _assert_engages(self, t: ProperType) -> None:
        result = _type_kernel.rust_get_property_type(t)
        assert result is not None, f"Rust get_property_type did not engage for {t}"

    def test_callable_returns_ret_type(self) -> None:
        callable_t = self.fx.callable(self.fx.str_type, self.fx.a)
        self._assert_par(callable_t, "A")
        self._assert_engages(callable_t)

    def test_overloaded_returns_first_ret_type(self) -> None:
        overloaded = Overloaded(
            [self.fx.callable(self.fx.str_type, self.fx.a), self.fx.callable(self.fx.b, self.fx.b)]
        )
        self._assert_par(overloaded, "A")
        self._assert_engages(overloaded)

    def test_plain_instance_unchanged(self) -> None:
        plain = self.fx.a
        self._assert_par(plain, "A")
        self._assert_engages(plain)


@skipUnless(_NATIVE_WIRE_ENABLED, "requires TEST_NATIVE_TYPE_KERNEL=1 and type_kernel ext")
class NativeOverloadNeverSuite(Suite):
    """Parity for the Rust overload argument-prefix ports (mypy.checker).

    `overload_can_never_match`, `is_more_general_arg_prefix` and
    `is_same_arg_prefix` rest on the native `is_callable_compatible` engine
    with the `is_more_precise` / `is_proper_subtype` / `is_same_type`
    predicates. The Rust fast path covers the non-generic
    Callable-vs-Callable branch only: a generic (non-empty `variables`)
    operand defers, because Python unifies a generic left via
    `unify_generic_callable` before the parameter check, and
    `is_more_general_arg_prefix`'s Overloaded branch defers because the
    FunctionLike zip stays in Python. Toggling the checker gate off (pure
    Python) and on (Rust seam) must produce identical booleans, and a direct
    seam call proves the Rust function engages rather than silently deferring
    on the fast path.
    """

    def setUp(self) -> None:
        from mypy.checker import _set_native_checker_active, _set_native_checker_resolver

        self.fx = TypeFixture()
        type_infos = []
        for name in dir(self.fx):
            if not name.endswith("i"):
                continue
            value = getattr(self.fx, name)
            if _is_type_info(value):
                type_infos.append(value)
        self.resolver = _type_kernel.build_native_resolver(type_infos, [])
        self._set_active = _set_native_checker_active
        self._set_resolver = _set_native_checker_resolver
        _set_native_checker_active(True)
        _set_native_checker_resolver(self.resolver)

    def tearDown(self) -> None:
        from mypy.checker import _set_native_checker_active, _set_native_checker_resolver

        _set_native_checker_active(False)
        _set_native_checker_resolver(None)

    def _with_gate(self, active: bool, fn: Callable[[], T]) -> T:
        self._set_active(active)
        try:
            return fn()
        finally:
            self._set_active(True)

    def _callable(
        self,
        args: list[Type],
        arg_kinds: list[ArgKind],
        ret: Type,
        variables: list[TypeVarLikeType] | None = None,
    ) -> CallableType:
        return CallableType(
            args, arg_kinds, [None] * len(args), ret, self.fx.function, variables=variables or []
        )

    def _par_bool(self, fn: Callable[[], bool], label: str) -> bool:
        off = self._with_gate(False, fn)
        assert isinstance(off, bool)
        on = self._with_gate(True, fn)
        assert isinstance(on, bool)
        assert_equal(on, off, f"{label} parity")
        return on

    def test_overload_never_match_broader(self) -> None:
        from mypy.checker import overload_can_never_match

        broader = self._callable([self.fx.o], [ARG_POS], self.fx.o)
        narrower = self._callable([self.fx.b], [ARG_POS], self.fx.o)
        result = self._par_bool(
            lambda: overload_can_never_match(broader, narrower), "overload_can_never_match"
        )
        # (object) is strictly broader than (B): the (B) overload can never
        # be matched.
        assert_equal(result, True)
        self._assert_overload_engages(broader, narrower)

    def test_overload_never_match_not_broader(self) -> None:
        from mypy.checker import overload_can_never_match

        narrower = self._callable([self.fx.b], [ARG_POS], self.fx.o)
        broader = self._callable([self.fx.o], [ARG_POS], self.fx.o)
        result = self._par_bool(
            lambda: overload_can_never_match(narrower, broader), "overload_can_never_match"
        )
        assert_equal(result, False)

    def test_overload_never_match_generic_defers(self) -> None:
        from mypy.checker import overload_can_never_match

        # signature carries a type var: the erase+expand / unify path defers
        # to Python, but on==off must still hold.
        sig = self._callable([self.fx.t], [ARG_POS], self.fx.o, variables=[self.fx.t])
        other = self._callable([self.fx.o], [ARG_POS], self.fx.o)
        self._par_bool(lambda: overload_can_never_match(sig, other), "overload_can_never_match")
        # The raw seam must defer (return None) on the generic operand.
        from mypy.checker import _serialize_type_for_checker

        raw = _type_kernel.rust_overload_can_never_match(
            _serialize_type_for_checker(sig),
            _serialize_type_for_checker(other),
            state.strict_optional,
            self.resolver,
        )
        assert raw is None, "Rust overload_can_never_match should defer on generic signature"

    def test_is_more_general_arg_prefix_wider(self) -> None:
        from mypy.checker import is_more_general_arg_prefix

        wider = self._callable([self.fx.o, self.fx.o], [ARG_POS, ARG_POS], self.fx.o)
        narrower = self._callable([self.fx.b, self.fx.a], [ARG_POS, ARG_POS], self.fx.o)
        result = self._par_bool(
            lambda: is_more_general_arg_prefix(wider, narrower), "is_more_general_arg_prefix"
        )
        assert_equal(result, True)
        self._assert_prefix_engages(wider, narrower)

    def test_is_more_general_arg_prefix_narrower(self) -> None:
        from mypy.checker import is_more_general_arg_prefix

        wider = self._callable([self.fx.o, self.fx.o], [ARG_POS, ARG_POS], self.fx.o)
        narrower = self._callable([self.fx.b, self.fx.a], [ARG_POS, ARG_POS], self.fx.o)
        result = self._par_bool(
            lambda: is_more_general_arg_prefix(narrower, wider), "is_more_general_arg_prefix"
        )
        assert_equal(result, False)

    def test_is_more_general_arg_prefix_overloaded_defers(self) -> None:
        from mypy.checker import is_more_general_arg_prefix

        t_items = [
            self._callable([self.fx.o], [ARG_POS], self.fx.o),
            self._callable([self.fx.a], [ARG_POS], self.fx.o),
        ]
        s_items = [
            self._callable([self.fx.b], [ARG_POS], self.fx.o),
            self._callable([self.fx.a], [ARG_POS], self.fx.o),
        ]
        t = Overloaded(t_items)
        s = Overloaded(s_items)
        # The Overloaded (FunctionLike) branch stays in Python; on==off holds
        # and the raw Callable-vs-Callable seam defers on an Overloaded.
        result = self._par_bool(
            lambda: is_more_general_arg_prefix(t, s), "is_more_general_arg_prefix"
        )
        assert isinstance(result, bool)

    def test_is_same_arg_prefix_parity(self) -> None:
        from mypy.checker import _serialize_type_for_checker, is_same_arg_prefix

        same = self._callable([self.fx.b], [ARG_POS], self.fx.o)
        other = self._callable([self.fx.o], [ARG_POS], self.fx.o)

        def raw(t: CallableType, s: CallableType) -> bool | None:
            return cast(
                "bool | None",
                _type_kernel.rust_is_same_arg_prefix(
                    _serialize_type_for_checker(t),
                    _serialize_type_for_checker(s),
                    state.strict_optional,
                    self.resolver,
                ),
            )

        def via_fn(t: CallableType, s: CallableType) -> bool:
            return is_same_arg_prefix(t, s)

        # Equal args -> True, with the covariant is_same_type check.
        assert_equal(self._par_bool(lambda: via_fn(same, same), "is_same_arg_prefix"), True)
        assert raw(same, same) is not None, "Rust is_same_arg_prefix did not engage"
        # Different args -> False.
        assert_equal(self._par_bool(lambda: via_fn(same, other), "is_same_arg_prefix"), False)
        assert raw(same, other) is not None, "Rust is_same_arg_prefix did not engage"

    def _assert_overload_engages(self, sig: CallableType, other: CallableType) -> None:
        from mypy.checker import _serialize_type_for_checker

        result = _type_kernel.rust_overload_can_never_match(
            _serialize_type_for_checker(sig),
            _serialize_type_for_checker(other),
            state.strict_optional,
            self.resolver,
        )
        assert result is not None, "Rust overload_can_never_match did not engage"

    def _assert_prefix_engages(self, t: CallableType, s: CallableType) -> None:
        from mypy.checker import _serialize_type_for_checker

        result = _type_kernel.rust_is_more_general_arg_prefix(
            _serialize_type_for_checker(t),
            _serialize_type_for_checker(s),
            state.strict_optional,
            self.resolver,
        )
        assert result is not None, "Rust is_more_general_arg_prefix did not engage"


@skipUnless(_NATIVE_WIRE_ENABLED, "requires TEST_NATIVE_TYPE_KERNEL=1 and type_kernel ext")
class NativeHasAnyTypeSuite(Suite):
    """Parity suite for the Rust `has_any_type` port with alias type-arg
    substitution (Phase B3b, #591).

    The B3b core: `has_any_type` must expand a `TypeAliasType` to its
    substituted target (like `_expand_once`) and answer correctly, not
    merely defer on every alias. Covers typevar aliases applied with Any
    (true), plain targets (false), chains, no_args aliases, cycles
    (defer), and new-style (PEP 695) arg visiting. Requires
    TEST_NATIVE_TYPE_KERNEL=1.
    """

    def setUp(self) -> None:
        from mypy.checkexpr import _set_native_checkexpr_active, _set_native_checkexpr_resolver

        self.fx = TypeFixture()
        self.resolver = self._build_resolver([])
        _set_native_checkexpr_resolver(self.resolver)
        _set_native_checkexpr_active(True)

    def tearDown(self) -> None:
        from mypy.checkexpr import _set_native_checkexpr_active, _set_native_checkexpr_resolver

        _set_native_checkexpr_active(False)
        _set_native_checkexpr_resolver(None)

    def _build_resolver(self, aliases: list[Any]) -> Any:
        return _type_kernel.build_native_resolver(
            [
                self.fx.oi,
                self.fx.ai,
                self.fx.bi,
                self.fx.str_type_info,
                self.fx.type_typei,
                self.fx.std_tuplei,
                self.fx.std_listi,
            ],
            aliases,
        )

    def _rebuild_with_aliases(self, aliases: list[Any]) -> None:
        from mypy.checkexpr import _set_native_checkexpr_resolver

        self.resolver = self._build_resolver(aliases)
        _set_native_checkexpr_resolver(self.resolver)

    def assert_rust_decides(self, t: Type, expected: bool) -> None:
        """Assert the Rust kernel answers `expected` without deferring."""
        from mypy.checkexpr import _serialize_type_for_checkexpr

        rusted = _type_kernel.rust_has_any_type(
            self.resolver, _serialize_type_for_checkexpr(t), False
        )
        assert rusted is not None, f"Rust deferred on {t!r}"
        assert rusted is expected

    def assert_rust_defers(self, t: Type) -> None:
        from mypy.checkexpr import _serialize_type_for_checkexpr

        rusted = _type_kernel.rust_has_any_type(
            self.resolver, _serialize_type_for_checkexpr(t), False
        )
        assert rusted is None, f"Rust should defer on {t!r}, got {rusted}"

    def _make_tvar(self, name: str, raw_id: int) -> TypeVarType:
        return TypeVarType(
            name, f"mod.{name}", TypeVarId(raw_id), [], self.fx.str_type, self.fx.nonet, 0
        )

    def _make_alias(
        self,
        fullname: str,
        target: Type,
        *,
        alias_tvars: list[TypeVarType] | None = None,
        no_args: bool = False,
    ) -> TypeAlias:
        from mypy.nodes import TypeAlias

        return TypeAlias(
            target,
            fullname,
            "mod",
            -1,
            -1,
            alias_tvars=alias_tvars or [],  # type: ignore[arg-type]
            no_args=no_args,
        )

    def test_plain_any(self) -> None:
        self.assert_rust_decides(AnyType(TypeOfAny.unannotated), True)

    def test_plain_instance_with_any(self) -> None:
        self.assert_rust_decides(
            Instance(self.fx.std_listi, [AnyType(TypeOfAny.unannotated)]), True
        )

    def test_plain_instance_clean(self) -> None:
        self.assert_rust_decides(Instance(self.fx.std_listi, [self.fx.str_type]), False)

    def test_special_form_any_not_contagious(self) -> None:
        self.assert_rust_decides(AnyType(TypeOfAny.special_form), False)

    def test_alias_without_typevars_no_any(self) -> None:
        # A = List[int]: target has no Any, old-style alias, no args to
        # visit → false.
        alias = self._make_alias("mod.A", Instance(self.fx.std_listi, [self.fx.a]))
        self._rebuild_with_aliases([alias])
        self.assert_rust_decides(TypeAliasType(alias, []), False)

    def test_alias_without_typevars_with_any_in_target(self) -> None:
        # A = List[Any]: target contains Any → true.
        alias = self._make_alias(
            "mod.A", Instance(self.fx.std_listi, [AnyType(TypeOfAny.unannotated)])
        )
        self._rebuild_with_aliases([alias])
        self.assert_rust_decides(TypeAliasType(alias, []), True)

    def test_alias_typevar_any_substitution_true(self) -> None:
        # A[T] = List[T], applied A[Any]: substitution must turn the
        # target into List[Any] → true. This is the B3b core case that
        # shape-only expansion answered incorrectly (false).
        tv = self._make_tvar("T", 1)
        alias = self._make_alias("mod.A", Instance(self.fx.std_listi, [tv]), alias_tvars=[tv])
        self._rebuild_with_aliases([alias])
        self.assert_rust_decides(TypeAliasType(alias, [AnyType(TypeOfAny.unannotated)]), True)

    def test_alias_typevar_int_substitution_false(self) -> None:
        # A[T] = List[T], applied A[int]: substituted target List[int]
        # has no Any → false.
        tv = self._make_tvar("T", 2)
        alias = self._make_alias("mod.A", Instance(self.fx.std_listi, [tv]), alias_tvars=[tv])
        self._rebuild_with_aliases([alias])
        self.assert_rust_decides(TypeAliasType(alias, [self.fx.a]), False)

    def test_alias_typevar_unused_arg_oldstyle_skipped(self) -> None:
        # Old-style generic alias with a dead typevar: A[T] = int,
        # applied A[Any]. Python's visit_type_alias_type visits only the
        # proper target (int) for old-style aliases, ignoring the args →

        # false. The Rust path must match (python_3_12 == False skips
        # args).
        tv = self._make_tvar("T", 3)
        alias = self._make_alias("mod.A", self.fx.str_type, alias_tvars=[tv])
        self._rebuild_with_aliases([alias])
        self.assert_rust_decides(TypeAliasType(alias, [AnyType(TypeOfAny.unannotated)]), False)

    def test_alias_typevar_unused_arg_python312_visits_args(self) -> None:
        # Same dead typevar but new-style (PEP 695): Python visits *both*
        # the proper target and (for python_3_12 aliases) the args, so
        # A[Any] → true. The fixture must fabricate a PEP 695 alias via

        # `python_3_12_type_alias=True`.
        tv = self._make_tvar("T", 4)
        alias = self._make_alias("mod.A", self.fx.str_type, alias_tvars=[tv])
        alias.python_3_12_type_alias = True
        self._rebuild_with_aliases([alias])
        self.assert_rust_decides(TypeAliasType(alias, [AnyType(TypeOfAny.unannotated)]), True)

    def test_alias_chain_typevar_any(self) -> None:
        # B = A[int], A[T] = List[T]: the chain loop must pass B's args
        # through A's substitution. B's target is a nested TypeAliasType
        # to A; A substitutes List[int]; no Any → false.
        tv = self._make_tvar("T", 5)
        alias_a = self._make_alias("mod.A", Instance(self.fx.std_listi, [tv]), alias_tvars=[tv])
        inner = TypeAliasType(alias_a, [self.fx.a])
        alias_b = self._make_alias("mod.B", inner, alias_tvars=[])
        self._rebuild_with_aliases([alias_a, alias_b])
        self.assert_rust_decides(TypeAliasType(alias_b, []), False)

    def test_alias_chain_to_any(self) -> None:
        # B = A, A = List[Any]: chain with no typevars, target carries
        # Any → true.
        alias_a = self._make_alias(
            "mod.A", Instance(self.fx.std_listi, [AnyType(TypeOfAny.unannotated)])
        )
        alias_b = self._make_alias("mod.B", TypeAliasType(alias_a, []), alias_tvars=[])
        self._rebuild_with_aliases([alias_a, alias_b])
        self.assert_rust_decides(TypeAliasType(alias_b, []), True)

    def test_alias_no_args(self) -> None:
        # L = List (no_args, production strips typevars at use sites).
        # Target List without args → no Any → false.
        alias = self._make_alias("mod.L", Instance(self.fx.std_listi, []), no_args=True)
        self._rebuild_with_aliases([alias])
        self.assert_rust_decides(TypeAliasType(alias, []), False)

    def test_alias_self_referential_cycle_defers(self) -> None:
        # A = List[A]: get_proper_type cannot terminate on the recursive
        # alias; the Rust path must not loop. The seen-set short-circuits
        # (mirroring BoolTypeQuery.seen_aliases) to the ANY_STRATEGY

        # default, which is False, the same answer Python's
        # visit_type_alias_type gives for a repeated alias.
        tv = self._make_tvar("T", 9)
        alias_a = self._make_alias("mod.A", Instance(self.fx.std_listi, [tv]), alias_tvars=[tv])
        # A's target references A itself (recursive): List[A].
        alias_a.target = Instance(self.fx.std_listi, [TypeAliasType(alias_a, [])])
        self._rebuild_with_aliases([alias_a])
        self.assert_rust_decides(TypeAliasType(alias_a, []), False)

    def test_alias_missing_snapshot_defers(self) -> None:
        # An alias whose fullname is not in the resolver snapshot: Rust
        # cannot expand → defer to Python.
        from mypy.nodes import TypeAlias

        tv = TypeVarType("U", "mod.U", TypeVarId(70), [], self.fx.str_type, self.fx.nonet, 0)
        alias = TypeAlias(
            Instance(self.fx.std_listi, [tv]), "mod.Unresolved", "mod", -1, -1, alias_tvars=[tv]
        )
        # Do NOT rebuild the resolver with this alias; it's missing.
        self.assert_rust_defers(TypeAliasType(alias, []))

    def test_union_with_alias_any(self) -> None:
        # Union[int, A] where A = List[Any]: the union arm behind the
        # alias carries Any → true.
        alias = self._make_alias(
            "mod.A", Instance(self.fx.std_listi, [AnyType(TypeOfAny.unannotated)])
        )
        self._rebuild_with_aliases([alias])
        u = UnionType.make_union([self.fx.a, TypeAliasType(alias, [])])
        self.assert_rust_decides(u, True)

    def test_bare_typevar_no_default_false(self) -> None:
        # Plain `T = TypeVar('T')`: the default is the
        # from_omitted_generics sentinel, which is not a real Any.

        # Python's HasAnyType.visit_type_var only visits the default when
        # has_default() is true (B3b regression: the sentinel was treated
        # as a real Any, so plain typevars spuriously reported Any).
        tv = TypeVarType(
            "T",
            "mod.T",
            TypeVarId(1),
            [],
            self.fx.str_type,
            AnyType(TypeOfAny.from_omitted_generics),
        )
        self.assert_rust_decides(tv, False)

    def test_bare_typevar_real_default_any_true(self) -> None:
        # `T = TypeVar('T', default=Any)`: a genuine Any default is a
        # real Any and must be detected.
        tv = TypeVarType(
            "T", "mod.T", TypeVarId(1), [], self.fx.str_type, AnyType(TypeOfAny.unannotated)
        )
        self.assert_rust_decides(tv, True)

    def test_bare_typevar_bound_any_true(self) -> None:
        # `T = TypeVar('T', bound=Any)`: the upper bound is visited
        # unconditionally by Python.
        tv = TypeVarType(
            "T",
            "mod.T",
            TypeVarId(1),
            [],
            AnyType(TypeOfAny.unannotated),
            AnyType(TypeOfAny.from_omitted_generics),
        )
        self.assert_rust_decides(tv, True)

    def test_bare_typevar_any_value_true(self) -> None:
        # `T = TypeVar('T', 'A', Any)`: a value restriction containing
        # Any is visited by Python (values are always queried).
        tv = TypeVarType(
            "T",
            "mod.T",
            TypeVarId(1),
            [AnyType(TypeOfAny.unannotated)],
            self.fx.str_type,
            AnyType(TypeOfAny.from_omitted_generics),
        )
        self.assert_rust_decides(tv, True)


@skipUnless(_NATIVE_WIRE_ENABLED, "requires TEST_NATIVE_TYPE_KERNEL=1 and type_kernel ext")
class NativeTupleExpandAndJoinSuite(Suite):
    """Parity suite for the `rust_build_tuple_type` seen_unpack reduce and
    the `join_type_list_inner` nominal Instance prejoin (issue #846).

    Port 1 (`unpack_expand_updated` in checkexpr_functions.rs): a tuple
    expression with exactly one star (e.g. `(*ts,)` where `ts:
    tuple[X, ...]`) previously deferred the whole `build_tuple_type`
    result to Python (`return Ok(None)` on `seen_unpack == 1`). The Rust
    side now expands the tuple with the empty substitution map, which is
    the identity except for the single-item normalization
    (expandtype.py:1009-1033): `Tuple[*tuple[X, ...]]` unwraps to the
    `tuple[X, ...]` Instance. A lone non-tuple Instance or TypeAliasType
    unpack still defers.

    Port 2 (`join_one_pair` prejoin in checkexpr_functions.rs): the
    args-less Instance-Instance nominal fold of `join.join_type_list`
    (used by the fast container literal path). When both items are
    plain `Instance`s with no args and no last_known_value, the join is
    decided by the shared `visit_instance_join` (same-type -> the type
    itself; subtype -> the supertype; else common ancestor) instead of
    falling through to the generic `join_types` fold. Behavior is
    identical to the Python twin; the Rust side now decides these cases
    inline, keeping the fold native for the nominal fast path.

    Each test asserts both parity (gate-off vs gate-on produce the same
    result string) and Rust engagement (the direct seam call returns a
    result rather than deferring).
    """

    def setUp(self) -> None:
        from mypy.checkexpr import _set_native_checkexpr_active, _set_native_checkexpr_resolver
        from mypy.wirefixup import set_wire_typeinfo_map

        self.fx = TypeFixture()
        infos = [
            self.fx.oi,
            self.fx.ai,
            self.fx.bi,
            self.fx.bool_type_info,
            self.fx.std_tuplei,
            self.fx.std_listi,
        ]
        self.resolver = _type_kernel.build_native_resolver(infos, [])
        self.wire_infos = {i.fullname: i for i in infos}
        set_wire_typeinfo_map(self.wire_infos)
        _set_native_checkexpr_resolver(self.resolver)
        _set_native_checkexpr_active(True)

    def tearDown(self) -> None:
        from mypy.checkexpr import _set_native_checkexpr_active, _set_native_checkexpr_resolver
        from mypy.wirefixup import set_wire_typeinfo_map

        _set_native_checkexpr_active(False)
        _set_native_checkexpr_resolver(None)
        set_wire_typeinfo_map(None)

    def _build_tuple(self, items: Sequence[Type], seen_unpack: int) -> Type | None:
        from mypy.checkexpr import _deserialize_type_from_checkexpr, _serialize_type_for_checkexpr

        items_bytes = [_serialize_type_for_checkexpr(t) for t in items]
        raw = _type_kernel.rust_build_tuple_type(items_bytes, seen_unpack)
        if raw is None:
            return None
        return _deserialize_type_from_checkexpr(bytes(raw))

    def _container(self, tag: str, items: Sequence[Type]) -> Type | None:
        from mypy.checkexpr import _deserialize_type_from_checkexpr, _serialize_type_for_checkexpr

        items_bytes = [_serialize_type_for_checkexpr(t) for t in items]
        raw = _type_kernel.rust_container_type(self.resolver, tag, items_bytes, None, 0)
        if raw is None:
            return None
        return _deserialize_type_from_checkexpr(bytes(raw))

    def test_single_star_any_tuple_unwraps(self) -> None:
        # (*ts,) with ts: tuple[Any, ...] -> tuple[Any, ...]. Python runs
        # expand_type(result, {}) which normalizes the lone unpack to the
        # tuple Instance. Rust now mirrors it.
        from mypy.checkexpr import _set_native_checkexpr_active

        items = [AnyType(TypeOfAny.special_form)]
        off = self._with_gate(_set_native_checkexpr_active, False, self._build_tuple, items, 1)
        on = self._build_tuple(items, 1)
        assert on is not None, "Rust build_tuple_type single-star did not engage"
        assert str(on) == str(off)

    def test_single_star_typevar_tuple_unpack_passthrough(self) -> None:
        # (*Ts,) with Ts a TypeVarTuple: lone unpack is not a tuple Instance,
        # so `unpack_expand_updated` returns the tuple UNCHANGED, matching
        # Python's `expand_type` identity. Keeps its `tuple[*Ts]` shape.
        tv = TypeVarTupleType(
            "Ts", "mod.Ts", TypeVarId(0), self.fx.o, self.fx.std_tuple, self.fx.anyt, min_len=0
        )
        items = [UnpackType(tv)]
        t = self._build_tuple(items, 1)
        assert t is not None, "Rust build_tuple_type did not engage"
        assert str(t) == "tuple[*Ts]"

    def test_multi_star_defers(self) -> None:
        # A tuple with two stars is not the seen_unpack == 1 case; the
        # Rust path returns the tuple directly (no expansion). Python
        # expands each item (identity with an empty map). Parity holds.
        from mypy.checkexpr import _set_native_checkexpr_active

        items = [self.fx.a, self.fx.b]
        off = self._with_gate(_set_native_checkexpr_active, False, self._build_tuple, items, 0)
        on = self._build_tuple(items, 0)
        assert on is not None, "Rust build_tuple_type did not engage"
        assert str(on) == str(off)

    def test_join_same_instance_engages(self) -> None:
        # [A, A] -> list[A]. The fixture TypeInfo uses the full builtins
        # prefix in str().
        t = self._container("list", [self.fx.a, self.fx.a])
        assert t is not None, "Rust container type did not engage"
        assert str(t) == "builtins.list[A]"

    def test_join_subtype_instance_engages(self) -> None:
        # [A, object] -> list[object]. The nominal prejoin resolves via
        # visit_instance_join (A <: object), where the old fold deferred.
        t = self._container("list", [self.fx.a, self.fx.o])
        assert t is not None, "Rust container type did not engage"
        assert str(t) == "builtins.list[builtins.object]"

    def test_join_pair_parity(self) -> None:
        # Same container literal through the gate-off (pure-Python
        # join_type_list) and gate-on (Rust seam) paths.
        from mypy.checkexpr import _set_native_checkexpr_active

        items = [self.fx.a, self.fx.o]
        off = self._with_gate(_set_native_checkexpr_active, False, self._container, "list", items)
        on = self._container("list", items)
        assert on is not None, "Rust container type did not engage"
        assert str(on) == str(off)

    def _with_gate(
        self, set_active: Any, active: bool, fn: Callable[..., Type | None], *args: Any
    ) -> Type | None:
        set_active(active)
        try:
            return fn(*args)
        finally:
            set_active(True)


@skipUnless(_NATIVE_WIRE_ENABLED, "requires TEST_NATIVE_TYPE_KERNEL=1 and type_kernel ext")
class NativeUninhabitedSuite(Suite):
    """Parity suite for the Rust `has_uninhabited_component` and
    `has_ambiguous_uninhabited_component` ports with alias expansion
    (Phase C, #594).

    Phase C closes the same gap B3b (#593) closed for `has_any_type`: the
    uninhabited-component queries must expand a `TypeAliasType` to its
    substituted target and answer correctly instead of deferring on every
    alias. Covers plain uninhabited types (true), clean instances (false),
    aliases with an uninhabited target (true), typevar aliases applied with
    an uninhabited arg (true), chains, and cycles (defer). Requires
    TEST_NATIVE_TYPE_KERNEL=1.
    """

    def setUp(self) -> None:
        from mypy.checkexpr import _set_native_checkexpr_active, _set_native_checkexpr_resolver

        self.fx = TypeFixture()
        self.resolver = self._build_resolver([])
        _set_native_checkexpr_resolver(self.resolver)
        _set_native_checkexpr_active(True)

    def tearDown(self) -> None:
        from mypy.checkexpr import _set_native_checkexpr_active, _set_native_checkexpr_resolver

        _set_native_checkexpr_active(False)
        _set_native_checkexpr_resolver(None)

    def _build_resolver(self, aliases: list[Any]) -> Any:
        return _type_kernel.build_native_resolver(
            [
                self.fx.oi,
                self.fx.ai,
                self.fx.bi,
                self.fx.str_type_info,
                self.fx.type_typei,
                self.fx.std_tuplei,
                self.fx.std_listi,
            ],
            aliases,
        )

    def _rebuild_with_aliases(self, aliases: list[Any]) -> None:
        from mypy.checkexpr import _set_native_checkexpr_resolver

        self.resolver = self._build_resolver(aliases)
        _set_native_checkexpr_resolver(self.resolver)

    def assert_uninhabited_decides(self, t: Type, expected: bool) -> None:
        """Assert the Rust kernel answers `expected` for has_uninhabited_component."""
        from mypy.checkexpr import _serialize_type_for_checkexpr

        rusted = _type_kernel.rust_has_uninhabited_component(
            _serialize_type_for_checkexpr(t), self.resolver
        )
        assert rusted is not None, f"Rust deferred on {t!r}"
        assert rusted is expected

    def assert_uninhabited_defers(self, t: Type) -> None:
        from mypy.checkexpr import _serialize_type_for_checkexpr

        rusted = _type_kernel.rust_has_uninhabited_component(
            _serialize_type_for_checkexpr(t), self.resolver
        )
        assert rusted is None, f"Rust should defer on {t!r}, got {rusted}"

    def assert_ambiguous_decides(self, t: Type, expected: bool) -> None:
        from mypy.checkexpr import _serialize_type_for_checkexpr

        rusted = _type_kernel.rust_has_ambiguous_uninhabited_component(
            _serialize_type_for_checkexpr(t), self.resolver
        )
        assert rusted is not None, f"Rust deferred on {t!r}"
        assert rusted is expected

    def assert_ambiguous_defers(self, t: Type) -> None:
        from mypy.checkexpr import _serialize_type_for_checkexpr

        rusted = _type_kernel.rust_has_ambiguous_uninhabited_component(
            _serialize_type_for_checkexpr(t), self.resolver
        )
        assert rusted is None, f"Rust should defer on {t!r}, got {rusted}"

    def _make_tvar(self, name: str, raw_id: int) -> TypeVarType:
        return TypeVarType(
            name, f"mod.{name}", TypeVarId(raw_id), [], self.fx.str_type, self.fx.nonet, 0
        )

    def _make_alias(
        self,
        fullname: str,
        target: Type,
        *,
        alias_tvars: list[TypeVarType] | None = None,
        no_args: bool = False,
    ) -> TypeAlias:
        from mypy.nodes import TypeAlias

        return TypeAlias(
            target,
            fullname,
            "mod",
            -1,
            -1,
            alias_tvars=alias_tvars or [],  # type: ignore[arg-type]
            no_args=no_args,
        )

    def _uninhabited(self, ambiguous: bool = False) -> UninhabitedType:
        return UninhabitedType(ambiguous=ambiguous)

    def test_plain_uninhabited_true(self) -> None:
        self.assert_uninhabited_decides(self._uninhabited(), True)

    def test_plain_uninhabited_ambiguous_true(self) -> None:
        self.assert_ambiguous_decides(self._uninhabited(ambiguous=True), True)

    def test_plain_uninhabited_not_ambiguous_false(self) -> None:
        self.assert_ambiguous_decides(self._uninhabited(ambiguous=False), False)

    def test_clean_instance_false(self) -> None:
        self.assert_uninhabited_decides(Instance(self.fx.std_listi, [self.fx.str_type]), False)

    def test_union_with_uninhabited_true(self) -> None:
        u = UnionType.make_union([self.fx.a, self._uninhabited()])
        self.assert_uninhabited_decides(u, True)

    def test_alias_target_uninhabited_true(self) -> None:
        # A = Uninhabited: expanding the alias finds the uninhabited
        # target, where B3b-era Rust deferred.
        alias = self._make_alias("mod.A", self._uninhabited())
        self._rebuild_with_aliases([alias])
        self.assert_uninhabited_decides(TypeAliasType(alias, []), True)
        self.assert_ambiguous_decides(TypeAliasType(alias, []), False)

    def test_alias_target_ambiguous_uninhabited_true(self) -> None:
        alias = self._make_alias("mod.A", self._uninhabited(ambiguous=True))
        self._rebuild_with_aliases([alias])
        self.assert_ambiguous_decides(TypeAliasType(alias, []), True)

    def test_alias_target_clean_false(self) -> None:
        # A = List[int]: no uninhabited component.
        alias = self._make_alias("mod.A", Instance(self.fx.std_listi, [self.fx.a]))
        self._rebuild_with_aliases([alias])
        self.assert_uninhabited_decides(TypeAliasType(alias, []), False)

    def test_alias_typevar_uninhabited_arg_true(self) -> None:
        # A[T] = List[T] applied A[Uninhabited]: substitution carries the
        # uninhabited arg into the target (Phase C core). New-style alias
        # so the args are visited too.
        tv = self._make_tvar("T", 1)
        alias = self._make_alias("mod.A", Instance(self.fx.std_listi, [tv]), alias_tvars=[tv])
        alias.python_3_12_type_alias = True
        self._rebuild_with_aliases([alias])
        self.assert_uninhabited_decides(TypeAliasType(alias, [self._uninhabited()]), True)

    def test_alias_typevar_clean_arg_false(self) -> None:
        # A[T] = List[T] applied A[int]: no uninhabited anywhere.
        tv = self._make_tvar("T", 2)
        alias = self._make_alias("mod.A", Instance(self.fx.std_listi, [tv]), alias_tvars=[tv])
        self._rebuild_with_aliases([alias])
        self.assert_uninhabited_decides(TypeAliasType(alias, [self.fx.a]), False)

    def test_alias_chain_to_uninhabited_true(self) -> None:
        # B = A, A = Uninhabited: chain resolves to the uninhabited target.
        alias_a = self._make_alias("mod.A", self._uninhabited())
        alias_b = self._make_alias("mod.B", TypeAliasType(alias_a, []), alias_tvars=[])
        self._rebuild_with_aliases([alias_a, alias_b])
        self.assert_uninhabited_decides(TypeAliasType(alias_b, []), True)

    def test_alias_without_snapshot_defers(self) -> None:
        # A TypeAliasType referencing a fullname with no snapshot in the
        # resolver: expansion cannot proceed, defer.
        alias = TypeAliasType(self._make_alias("mod.Missing", self.fx.a), [])
        self.assert_uninhabited_defers(alias)
        self.assert_ambiguous_defers(alias)


@skipUnless(_NATIVE_WIRE_ENABLED, "requires TEST_NATIVE_TYPE_KERNEL=1 and type_kernel ext")
class NativeHasErasedComponentSuite(Suite):
    """Parity suite for the Rust `has_erased_component` port (slice 48).

    `has_erased_component` mirrors `HasErasedComponentsQuery`, a
    `BoolTypeQuery(ANY_STRATEGY)` whose only override is
    `visit_erased_type -> True` (checkexpr.py:8060-8071). The Rust wire
    walk delegates to the same alias expansion as the uninhabited query, so
    this suite covers the erased leaf directly, unions, clean instances,
    alias targets (true/false), and recursive aliases (defer).
    """

    def setUp(self) -> None:
        from mypy.checkexpr import _set_native_checkexpr_active, _set_native_checkexpr_resolver

        self.fx = TypeFixture()
